UPGRADE_BASE_COST = {
    "Common":200,"Uncommon":400,"Rare":700,"Epic":1200,"Legendary":2500,"Godly":5000
}

def get_upgrade_cost(rarity: str, current_level: int) -> int:
    base = UPGRADE_BASE_COST.get(rarity, 200)
    return int(base * (1.6 ** current_level))

def get_pokemon_rarity(pid: int) -> str:
    godly_ids = {p[0] for p in GODLY_POKEMON}
    if pid in godly_ids:         return "Godly"
    if pid in LEGENDARY_IDS:     return "Legendary"
    if pid in RARE_IDS:
        return "Epic" if random.random() < 0.3 else "Rare"
    roll = random.random()
    if roll < 0.50: return "Common"
    if roll < 0.80: return "Uncommon"
    if roll < 0.95: return "Rare"
    return "Epic"

def get_player_max_hp(pk: dict, medallion: int) -> int:
    level   = pk.get("level", 1)
    rarity  = pk.get("rarity", "Common")
    base_hp = 80 + level * 2
    r_mult  = RARITY_HP_MULT.get(rarity, 1.0)
    m_mult  = MEDALLION_HP_BOOST.get(medallion, 1.0)
    hp_lvl  = pk.get("hp_upgrade", 0)
    u_mult  = HP_UPGRADE_MULTS[min(hp_lvl, 5)]
    return int(base_hp * r_mult * m_mult * u_mult)

def get_effective_dmg(base_dmg: tuple, pk: dict) -> tuple:
    rarity   = pk.get("rarity", "Common")
    r_mult   = RARITY_DMG_MULT.get(rarity, 1.0)
    s_mult   = 1.5 if pk.get("shiny_variant") else 1.0
    d_lvl    = pk.get("dmg_upgrade", 0)
    u_mult   = DMG_UPGRADE_MULTS[min(d_lvl, 5)]
    total    = r_mult * s_mult * u_mult
    return (max(1, int(base_dmg[0]*total)), max(1, int(base_dmg[1]*total)))

def get_crit_chance(pk: dict) -> float:
    lvl = pk.get("crit_chance_upgrade", 0)
    return CRIT_CHANCE_VALUES[min(lvl, 5)]

def get_crit_dmg(pk: dict) -> float:
    lvl = pk.get("crit_dmg_upgrade", 0)
    return CRIT_DMG_VALUES[min(lvl, 10)]

def get_acc_upgrade_cost(rarity: str, current_level: int) -> int:
    base = UPGRADE_BASE_COST.get(rarity, 200) * 3
    return int(base * (1.8 ** current_level))

def get_godly_acc(move_acc: float, pk: dict) -> float:
    rarity = pk.get("rarity", "Common")
    if rarity not in ("Godly",): return move_acc
    if move_acc >= 1.0: return 1.0
    lvl = pk.get("acc_upgrade", 0)
    return ACC_UPGRADE_VALUES[min(lvl, 9)]

def get_dodge_chance(pk: dict) -> float:
    lvl   = pk.get("dodge_upgrade", 0)
    base  = DODGE_CHANCE_VALUES[min(lvl, 5)]
    trait = SHINY_GODLY_TRAITS.get(pk.get("species", ""), {})
    if trait.get("type") == "dodge":
        base = max(base, trait["value"])
    pktrait = POKEMON_TRAITS.get(pk.get("trait", ""), {})
    if pktrait.get("id") in ("Shadow Cloak", "Wind Rider", "Aqua Veil"):
        base = max(base, 0.20)
    return base

def get_lifesteal(pk: dict) -> float:
    lvl   = pk.get("lifesteal_upgrade", 0)
    base  = LIFESTEAL_VALUES[min(lvl, 5)]
    trait = SHINY_GODLY_TRAITS.get(pk.get("species", ""), {})
    if trait.get("type") == "lifesteal":
        base = max(base, trait["value"])
    pktrait = POKEMON_TRAITS.get(pk.get("trait", ""), {})
    if pktrait.get("id") == "Natural Cure":
        base = max(base, 0.08)
    return base

def get_speed_priority(pk: dict) -> float:
    lvl = pk.get("speed_upgrade", 0)
    return SPEED_PRIORITY_VALUES[min(lvl, 4)]

def get_type_multiplier(attack_type: str, defender_type: str) -> float:
    eff = TYPE_EFFECTIVENESS.get(attack_type, {})
    if defender_type in eff.get("immune", []):
        return 0.0
    if defender_type in eff.get("strong", []):
        return 2.0
    if defender_type in eff.get("weak", []):
        return 0.5
    return 1.0

def roll_trait_for_pokemon(pk: dict) -> str:
    # Weighted category selection — sums to exactly 100%
    # Common 45 + Rare 27 + Epic 14 + Legendary 9 + Mythic 4 + Secret 0.8 + Supreme 0.2 = 100
    _CAT_WEIGHTS = [45, 27, 14, 9, 4, 0.8, 0.2]
    _CAT_NAMES   = ["Common","Rare","Epic","Legendary","Mythic","Secret","Supreme"]
    cat = random.choices(_CAT_NAMES, weights=_CAT_WEIGHTS, k=1)[0]
    cat_data = TRAIT_CATEGORIES.get(cat, TRAIT_CATEGORIES["Common"])
    # Small type-trait bias (15% max) — reduced from 40% to prevent repeated same traits
    ptype = pk.get("type", "normal")
    type_traits = TYPE_TRAIT_MAP.get(ptype, [])
    if type_traits and random.random() < 0.15:
        return random.choice(type_traits)
    return random.choice(cat_data["traits"])

