def get_pokemon_moves(pokemon_id: int, pokemon_type: str, pokemon_name: str = "") -> list:
    name_key = pokemon_name.strip() if pokemon_name else ""
    if name_key in GODLY_MOVES:
        return GODLY_MOVES[name_key]
    if pokemon_id in LEGENDARY_MOVES:
        return LEGENDARY_MOVES[pokemon_id]
    return TYPE_MOVES.get(pokemon_type, TYPE_MOVES["normal"])

