def get_type_matchups(pokemon_type: str) -> dict:
    """Return what attack types a pokemon_type defender is weak to, resists, or is immune to."""
    TYPE_ICONS = {
        "fire":"🔥","water":"💧","grass":"🌿","electric":"⚡","psychic":"🔮","dark":"🌑",
        "dragon":"🐲","ghost":"👻","ice":"❄️","fighting":"🥊","poison":"☠️","ground":"🌍",
        "rock":"🪨","steel":"⚙️","fairy":"🌸","normal":"⚪","flying":"🌬️","bug":"🐛",
    }
    weak_to   = []
    resists   = []
    immune_to = []
    for atk_type, eff in TYPE_EFFECTIVENESS.items():
        icon = TYPE_ICONS.get(atk_type, "")
        if pokemon_type in eff.get("strong", []):
            weak_to.append(f"{icon}{atk_type.capitalize()}")
        if pokemon_type in eff.get("weak", []):
            resists.append(f"{icon}{atk_type.capitalize()}")
        if pokemon_type in eff.get("immune", []):
            immune_to.append(f"{icon}{atk_type.capitalize()}")
    return {"weak_to": weak_to, "resists": resists, "immune_to": immune_to}

