#  DATA LAYER
DATA_DIR = Path(__file__).parent / "data"
DATA_DIR.mkdir(exist_ok=True)

_DEFAULTS: dict = {
    "warnings":{},"autoresponses":{},"sticky":{},"pokemon":{},"cards":{},
    "server_settings":{},"stats_channels":{},"confessions":{},"afk":{},
    "giveaways":{},"marketplace":{},"whitelist":[],"pokemonlist":[],"nukerlist":[],"nuker_logs":[],
}

def load(name: str) -> dict:
    p = DATA_DIR / f"{name}.json"
    if not p.exists():
        default = _DEFAULTS.get(name, {})
        p.write_text(json.dumps(default))
    try:
        return json.loads(p.read_text())
    except Exception:
        return dict(_DEFAULTS.get(name, {}))

def save(name: str, data):
    p = DATA_DIR / f"{name}.json"
    p.write_text(json.dumps(data, indent=2))

def gdata(data: dict, guild_id) -> dict:
    key = str(guild_id)
    if key not in data:
        data[key] = {}
    return data[key]

def is_staff(member: discord.Member) -> bool:
    if member.guild_permissions.administrator:
        return True
    return any(r.name in STAFF_ROLE_NAMES for r in member.roles)

def is_owner(user) -> bool:
    return user.id == OWNER_ID

async def _check_owner_or_whitelist(interaction: discord.Interaction) -> bool:
    """Returns True if owner or whitelisted."""
    if interaction.user.id == OWNER_ID:
        return True
    if interaction.user.id in WHITELIST_USERS:
        return True
    return False

async def _check_owner_or_whitelist_ctx(ctx) -> bool:
    """ctx version — returns True if owner or whitelisted."""
    if ctx.author.id == OWNER_ID:
        return True
    if ctx.author.id in WHITELIST_USERS:
        return True
    return False

# Stores pending command approvals: key = message_id of owner DM → user_id
_PENDING_APPROVALS: dict = {}

class PendingCommandView(discord.ui.View):
    """Dropdown sent to owner when someone uses an unauthorized owner command."""
    def __init__(self, user_id: int, cmd_name: str, channel_id: int, execute_fn=None):
        super().__init__(timeout=300)
        self.user_id    = user_id
        self.cmd_name   = cmd_name
        self.channel_id = channel_id
        self.execute_fn = execute_fn   # async callable — runs the actual command on accept
        self.decided    = False

    @discord.ui.select(
        placeholder="Choose an action...",
        options=[
            discord.SelectOption(label="✅ Accept", value="accept", description="Approve and execute the command for the user"),
            discord.SelectOption(label="❌ Decline", value="decline", description="Deny — user is notified the request was declined"),
        ]
    )
    async def decision_select(self, interaction: discord.Interaction, select: discord.ui.Select):
        if self.decided:
            return await interaction.response.send_message("Already decided.", ephemeral=False)
        self.decided = True
        for item in self.children:
            item.disabled = True
        choice = select.values[0]
        if choice == "accept":
            await interaction.response.send_message(
                embed=discord.Embed(title="✅ Accepted", description="Executing command for user…", color=COLORS["success"])
            )
            try: await interaction.message.edit(view=self)
            except Exception: pass
            # Run the actual command if a callback was supplied
            if self.execute_fn:
                try:
                    await self.execute_fn(interaction.client)
                except Exception as ex:
                    try:
                        ch = interaction.client.get_channel(self.channel_id)
                        if ch:
                            await ch.send(embed=discord.Embed(description=f"❌ Command execution failed: `{ex}`", color=COLORS["error"]))
                    except Exception:
                        pass
            # DM the user to let them know it went through
            try:
                user = await interaction.client.fetch_user(self.user_id)
                await user.send(embed=discord.Embed(
                    title="✅ Request Accepted",
                    description=f"Your request for `{self.cmd_name}` was **accepted** and executed by the owner.",
                    color=COLORS["success"]
                ))
            except Exception:
                pass
        else:
            try: await interaction.message.edit(view=self)
            except Exception: pass
            try:
                user = await interaction.client.fetch_user(self.user_id)
                await user.send(embed=discord.Embed(
                    title="❌ Command Declined",
                    description=f"Your request for `{self.cmd_name}` was **declined** by the owner.",
                    color=COLORS["error"]
                ))
            except Exception:
                pass
            await interaction.response.send_message(
                embed=discord.Embed(title="❌ Declined", description="User has been notified.", color=COLORS["error"])
            )

async def _reject_owner_only(interaction: discord.Interaction, execute_fn=None) -> None:
    """Show 'Pending Command' to user and DM owner with Accept/Decline dropdown."""
    # Defer immediately so the 3-second Discord window never expires while we fetch_user
    if not interaction.response.is_done():
        await interaction.response.defer(ephemeral=False)
    # Whitelisted users — skip the owner DM entirely, just deny silently
    if interaction.user.id in WHITELIST_USERS:
        await interaction.followup.send(
            embed=discord.Embed(description="❌ This command is owner-only.", color=COLORS["error"]),
            ephemeral=False,
        )
        return
    cmd_name   = getattr(interaction.command, "name", "unknown")
    server_str = f"{interaction.guild.name} (`{interaction.guild.id}`)" if interaction.guild else "DM"
    channel_id = interaction.channel_id or 0
    # Build full command string — resolve user/channel/role IDs → names
    try:
        data      = interaction.data or {}
        resolved  = data.get("resolved", {})
        r_users   = resolved.get("users",    {})
        r_channels= resolved.get("channels", {})
        r_roles   = resolved.get("roles",    {})

        def _fmt_val(val):
            s = str(val)
            if s in r_users:
                u = r_users[s]
                return f"@{u.get('global_name') or u.get('username', s)}"
            if s in r_channels:
                return f"#{r_channels[s].get('name', s)}"
            if s in r_roles:
                return f"@{r_roles[s].get('name', s)}"
            return s

        def _flatten(opts, prefix=""):
            parts = []
            for o in opts:
                t = o.get("type", 0)
                if t in (1, 2):          # SUB_COMMAND / SUB_COMMAND_GROUP
                    parts += _flatten(o.get("options", []), prefix=f"{o['name']} ")
                else:
                    parts.append(f"{o['name']}: {_fmt_val(o.get('value', ''))}")
            return parts

        raw_opts  = data.get("options", [])
        args_parts = _flatten(raw_opts)
        full_cmd   = f"/{cmd_name}" + (f"  [{', '.join(args_parts)}]" if args_parts else "")
    except Exception:
        full_cmd = f"/{cmd_name}"
    try:
        owner = await interaction.client.fetch_user(OWNER_ID)
        e = discord.Embed(title="⚠️ Pending Command Approval", color=0xFF4500)
        e.add_field(name="👤 User",        value=f"**{interaction.user}** (`{interaction.user.id}`)", inline=False)
        e.add_field(name="📟 Full Command", value=f"```\n{full_cmd[:950]}\n```",                      inline=False)
        e.add_field(name="🖥️ Server",       value=server_str,                                          inline=False)
        e.set_footer(text="Accept → executes the command | Decline → user notified")
        await owner.send(embed=e, view=PendingCommandView(interaction.user.id, full_cmd, channel_id, execute_fn))
    except Exception:
        pass
    await interaction.followup.send(
        embed=discord.Embed(
            title="⏳ Pending Command",
            description="This command needs owner approval. You'll get a DM when it's decided.",
            color=COLORS["warn"]
        ), ephemeral=False
    )

async def _reject_owner_only_ctx(ctx, execute_fn=None) -> None:
    """Show 'Pending Command' to user and DM owner with Accept/Decline dropdown."""
    # For slash hybrid commands, defer immediately so fetch_user never causes a timeout
    if ctx.interaction and not ctx.interaction.response.is_done():
        await ctx.defer(ephemeral=False)
    # Whitelisted users — skip the owner DM entirely, just deny silently
    if ctx.author.id in WHITELIST_USERS:
        await ctx.send(embed=discord.Embed(description="❌ This command is owner-only.", color=COLORS["error"]))
        return
    cmd_name   = ctx.command.name if ctx.command else "unknown"
    server_str = f"{ctx.guild.name} (`{ctx.guild.id}`)" if ctx.guild else "DM"
    channel_id = ctx.channel.id if ctx.channel else 0
    full_cmd   = ctx.message.content if ctx.message else f",{cmd_name}"
    try:
        owner = await ctx.bot.fetch_user(OWNER_ID)
        e = discord.Embed(title="⚠️ Pending Command Approval", color=0xFF4500)
        e.add_field(name="👤 User",         value=f"**{ctx.author}**\nID: `{ctx.author.id}`", inline=False)
        e.add_field(name="📟 Full Command",  value=f"`{full_cmd[:200]}`",                      inline=False)
        e.add_field(name="🖥️ Server",        value=server_str,                                  inline=False)
        e.set_footer(text="Accept → executes the command | Decline → user notified")
        await owner.send(embed=e, view=PendingCommandView(ctx.author.id, full_cmd[:200], channel_id, execute_fn))
    except Exception:
        pass
    await ctx.send(embed=discord.Embed(
        title="⏳ Pending Command",
        description="This command needs owner approval. You'll get a DM when it's decided.",
        color=COLORS["warn"]
    ))

def parse_duration(s: str):
    units = {"s":1,"m":60,"h":3600,"d":86400}
    m = re.fullmatch(r"(\d+)([smhd])", s.lower())
    if not m:
        return None
    return int(m.group(1)) * units[m.group(2)]

def format_duration(secs: int) -> str:
    if secs < 60:   return f"{secs}s"
    if secs < 3600: return f"{secs//60}m {secs%60}s"
    h = secs // 3600; m2 = (secs % 3600) // 60
    return f"{h}h {m2}m"

#  POKEMON DATA HELPERS
def _default_items() -> dict:
    return {k: 0 for k in SHOP_ITEMS}

def get_pokemon_data(uid: str) -> dict:
    data = load("pokemon")
    if uid not in data:
        data[uid] = {
            "pokemon":[],"selected":0,"badges":[],"next_id":1,
            "balance":0,"pokeballs":{"pokeball":5},
            "packs":{"basic":0,"rare":0,"epic":0,"legendary":0,"master":0,"godly":0,"omega":0,"shiny_omega":0,"boss":0,"super_boss":0},
            "last_daily":None,"daily_streak":0,"trainer_level":1,
            "pokefight_medallions":0,"pokefight_current_waves":0,
            "pokefight_total_waves":0,"pokefight_boss_ready":False,"pokefight_wins":0,"pokefight_losses":0,"coins_earned":0,
            "party":[],"items":_default_items(),
        }
        save("pokemon", data)
    ud = data[uid]
    for k,v in [("balance",0),("pokeballs",{"pokeball":5}),("last_daily",None),
                ("daily_streak",0),("trainer_level",1),("next_id",1),
                ("pokefight_medallions",0),("pokefight_current_waves",0),
                ("pokefight_total_waves",0),("pokefight_boss_ready",False),
                ("pokefight_wins",0),("pokefight_losses",0),("coins_earned",0),
                ("party",[]),("pokemon",[]),("packs",{}),("items",{})]:
        ud.setdefault(k, v)
    for pk in CARD_PACKS:
        ud["packs"].setdefault(pk, 0)
    for itm in SHOP_ITEMS:
        ud["items"].setdefault(itm, 0)
    return ud

def save_pokemon_data(uid: str, ud: dict):
    data = load("pokemon")
    data[uid] = ud
    save("pokemon", data)

