def _day_key():
    import datetime
    return datetime.date.today().isoformat()

def _week_key():
    import datetime
    d = datetime.date.today()
    return f"{d.isocalendar()[0]}-W{d.isocalendar()[1]:02d}"

def get_quest_data(uid: str) -> dict:
    data = load("quests")
    if uid not in data:
        data[uid] = {}
    qd = data[uid]
    today = _day_key()
    week  = _week_key()
    if qd.get("day") != today:
        for q in DAILY_QUESTS:
            qd[q["key"]] = 0
            qd[q["key"] + "_claimed"] = False
        qd["day"] = today
    if qd.get("week") != week:
        for q in WEEKLY_QUESTS:
            qd[q["key"]] = 0
            qd[q["key"] + "_claimed"] = False
        qd["week"] = week
    data[uid] = qd
    save("quests", data)
    return qd

def save_quest_data(uid: str, qd: dict):
    data = load("quests")
    data[uid] = qd
    save("quests", data)

def increment_quest_stat(uid: str, stat: str, amount: int = 1):
    qd = get_quest_data(uid)
    if stat in qd:
        qd[stat] = qd.get(stat, 0) + amount
    else:
        qd[stat] = amount
    save_quest_data(uid, qd)

def get_cards_data(uid: str) -> dict:
    data = load("cards")
    if uid not in data:
        data[uid] = {"cards":[], "next_id":1}
        save("cards", data)
    cd = data[uid]
    cd.setdefault("cards", [])
    cd.setdefault("next_id", 1)
    return cd

