def roll_ivs() -> dict:
    return {s: random.randint(0,31) for s in ["hp","atk","def","spa","spd","spe"]}

def iv_percentage(ivs: dict) -> int:
    total = sum(ivs.values())
    return round(total / 186 * 100)

def pokemon_sprite_url(pid: int, shiny: bool = False) -> str:
    base = "https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/pokemon"
    return f"{base}/shiny/{pid}.png" if shiny else f"{base}/{pid}.png"

def pokemon_official_art(pid: int) -> str:
    return (f"https://raw.githubusercontent.com/PokeAPI/sprites/master/"
            f"sprites/pokemon/other/official-artwork/{pid}.png")

def get_coin_multiplier(uid: str) -> float:
    """Returns total coin multiplier including medallion boost and active coin boost."""
    ud   = get_pokemon_data(uid)
    base = MEDALLION_COIN_BOOST.get(ud.get("pokefight_medallions", 0), 1.0)
    # Check active coin boost
    expire = ACTIVE_COIN_BOOSTS.get(uid, 0)
    if time.time() < expire:
        base *= 1.5
    else:
        ACTIVE_COIN_BOOSTS.pop(uid, None)
    return base

def apply_medal_boost(uid: str, amount: int) -> int:
    return int(amount * get_coin_multiplier(uid))

def calc_sell_price(pk: dict) -> int:
    pid    = pk.get("pokedex_id", 0)
    rarity = pk.get("rarity", "Common")
    ivpct  = iv_percentage(pk.get("ivs", roll_ivs()))
    if pid in LEGENDARY_IDS:
        base = random.randint(300, 600)
    elif pid in RARE_IDS:
        base = random.randint(80, 180)
    elif rarity == "Common":
        # Common Pokemon should sell for LESS than a Pokeball (50 coins) — they're trash
        base = random.randint(5, 20)
    else:
        base = random.randint(25, 50)
    if pk.get("shiny") or pk.get("shiny_variant"):
        base = int(base * 2.0)
    price = int(base * (1 + ivpct / 200))
    if pid in LEGENDARY_IDS:
        price = min(price, 3000)
    elif pid in RARE_IDS:
        price = min(price, 600)
    elif rarity == "Common":
        price = min(price, 40)   # always less than a Pokeball (50 coins)
    else:
        price = min(price, 150)
    return max(3, price)

def make_owner_op(uid: str):
    ud = get_pokemon_data(uid)
    ud["pokefight_medallions"] = 5
    ud["pokefight_current_waves"] = 0
    ud["pokefight_total_waves"] = 999
    ud["pokefight_boss_ready"] = False
    ud["balance"] = max(ud.get("balance", 0), 9999999)
    for pk_name in CARD_PACKS:
        ud["packs"][pk_name] = max(ud["packs"].get(pk_name, 0), 1000)
    ud["pokeballs"]["masterball"]  = max(ud["pokeballs"].get("masterball", 0), 999)
    ud["pokeballs"]["ultraball"]   = max(ud["pokeballs"].get("ultraball", 0), 999)
    ud["pokeballs"]["greatball"]   = max(ud["pokeballs"].get("greatball", 0), 999)
    ud["pokeballs"]["pokeball"]    = max(ud["pokeballs"].get("pokeball", 0), 999)
    for itm in SHOP_ITEMS:
        ud["items"][itm] = max(ud["items"].get(itm, 0), 100)
    ud["items"]["trait_reroll"] = max(ud["items"].get("trait_reroll", 0), 999)
    # Add all Godly Pokémon
    existing_species = {p["species"] for p in ud["pokemon"]}
    next_id = ud.get("next_id", 2)
    for pid, name, ptype in GODLY_POKEMON:
        if name not in existing_species:
            pk = {
                "id": next_id, "species": name, "pokedex_id": pid,
                "level": 100, "ivs": {"hp":31,"atk":31,"def":31,"spa":31,"spd":31,"spe":31},
                "shiny": True, "shiny_variant": True,
                "nickname": None, "favorite": True, "moves": [], "type": ptype,
                "rarity": "Godly", "is_dead": False,
                "dmg_upgrade": 5, "hp_upgrade": 5,
                "crit_chance_upgrade": 5, "crit_dmg_upgrade": 5,
                "acc_upgrade": 9,
                "trait": "Multiscale",
            }
            ud["pokemon"].append(pk)
            existing_species.add(name)
            next_id += 1
    # Add all Supreme Pokémon
    for pid, name, ptype in SUPREME_POKEMON:
        if name not in existing_species:
            pk = {
                "id": next_id, "species": name, "pokedex_id": pid,
                "level": 100, "ivs": {"hp":31,"atk":31,"def":31,"spa":31,"spd":31,"spe":31},
                "shiny": True, "shiny_variant": True,
                "nickname": None, "favorite": True, "moves": [], "type": ptype,
                "rarity": "Supreme", "is_dead": False,
                "dmg_upgrade": 5, "hp_upgrade": 5,
                "crit_chance_upgrade": 5, "crit_dmg_upgrade": 5,
                "acc_upgrade": 9,
                "trait": "Wonder Guard",
            }
            ud["pokemon"].append(pk)
            existing_species.add(name)
            next_id += 1
    ud["next_id"] = next_id
    save_pokemon_data(uid, ud)

#  CARD HELPERS
# Hard ceiling on what tier a pack can roll — prevents money glitch
PACK_TIER_CEILING = {
    "basic":     "Common",      # 0% — only Common
    "rare":      "Rare",        # 0% — max Rare
    "epic":      "Epic",        # 0% — max Epic
    "legendary": "Ultra Rare",  # 5% chance up to Ultra Rare/Secret
    "master":    "Secret",
    "godly":     "Godly",
    "omega":      "Supreme",
    "shiny_omega":"Supreme",
    "boss":       "Boss",
    "super_boss": "Shiny Boss",
}

def roll_card_tier(pack_key: str, force_godly: bool = False) -> str:
    if force_godly or pack_key == "godly":
        return "Godly"
    if pack_key in ("omega", "shiny_omega"):
        return "Supreme"  # fallback only; open_card_pack handles these specially
    pack = CARD_PACKS[pack_key]
    guaranteed = pack["guaranteed"]
    g_idx = TIER_ORDER.index(guaranteed)
    ceiling   = PACK_TIER_CEILING.get(pack_key, "Secret")
    ceil_idx  = TIER_ORDER.index(ceiling)
    # Legendary pack: only 5% chance to go above Legendary
    if pack_key == "legendary" and random.random() >= 0.05:
        ceiling  = "Legendary"
        ceil_idx = TIER_ORDER.index(ceiling)
    if pack_key == "master" and random.random() < 0.01:
        return "Shiny Godly"  # 1% shiny godly in master pack (handled in open_card_pack)
    roll = random.random()
    cumulative = 0.0
    for tier in reversed(TIER_ORDER[:-2]):   # exclude Godly/Supreme from random pool
        if TIER_ORDER.index(tier) > ceil_idx:
            continue   # above this pack's ceiling — skip
        cumulative += CARD_TIERS[tier]["rate"]
        if roll < cumulative:
            if TIER_ORDER.index(tier) < g_idx:
                return guaranteed
            return tier
    return guaranteed

def open_card_pack(uid: str, pack_key: str) -> tuple:
    """Returns (opened_cards, auto_sold_coins). Reads fresh data to avoid duplication."""
    pack  = CARD_PACKS[pack_key]
    count = pack["cards"]
    cd    = get_cards_data(uid)
    ud    = get_pokemon_data(uid)
    # Uniqueness key: (pokemon_id, species_name, tier) — allows same-pid different forms
    owned_set   = {(c["pokemon_id"], c.get("species",""), c["tier"]) for c in cd.get("cards", [])}
    owned_species = {p["species"] for p in ud.get("pokemon", [])}
    opened      = []
    auto_coins  = 0
    new_pokemon = []
    # Omega packs give exactly 1 card of each tier (index maps to tier)
    OMEGA_TIERS  = ["Common", "Rare", "Epic", "Legendary", "Godly", "Supreme"]

    for i in range(count):
        tier = "Common"
        if pack_key == "master" and i < 2:
            tier = "Secret"
        elif pack_key == "godly":
            tier = "Godly"
        elif pack_key in ("omega", "shiny_omega"):
            tier = OMEGA_TIERS[i % len(OMEGA_TIERS)]
        elif pack_key == "boss":
            tier = "Boss"
        elif pack_key == "super_boss":
            tier = "Shiny Boss"
        else:
            tier = roll_card_tier(pack_key)

        # Shiny Omega forces all cards shiny
        force_shiny = (pack_key == "shiny_omega")

        # Resolve Pokémon from tier
        is_shiny_v = False
        if tier == "Shiny Godly":
            # 1% shiny godly from master pack — pick a random Shiny Godly
            pid, pname, ptype = random.choice(GODLY_POKEMON)
            pname = f"Shiny {pname}" if not pname.startswith("Shiny") else pname
            if pname not in {n for _,n,_ in GODLY_POKEMON}:
                pid, pname, ptype = random.choice([(p,n,t) for p,n,t in GODLY_POKEMON if n.startswith("Shiny")] or GODLY_POKEMON)
            is_shiny_v = True
            tier = "Godly"
        elif tier == "Godly":
            # Exclude Shiny Arceus from master pack
            godly_pool = GODLY_POKEMON if pack_key != "master" else [
                (p,n,t) for p,n,t in GODLY_POKEMON if n != "Shiny Arceus"
            ]
            pid, pname, ptype = random.choice(godly_pool)
            is_shiny_v = pname in SHINY_GODLY_NAMES
        elif tier == "Supreme":
            pid, pname, ptype = random.choice(SUPREME_POKEMON)
        elif tier == "Boss":
            pid, pname, ptype = random.choice(BOSS_RARITY_POKEMON)
            is_shiny_v = False
        elif tier == "Shiny Boss":
            pid, pname, ptype = random.choice(BOSS_RARITY_POKEMON)
            pname = f"Shiny {pname}"
            is_shiny_v = True
        else:
            entry = random.choice(POKEMON_CARD_POOL)
            pid, pname, ptype = entry
            is_shiny_v = random.random() < SHINY_VARIANT_RATE

        # Shiny Supreme upgrade:
        # - Omega pack: 1% chance per Supreme card to become Shiny Supreme
        # - Shiny Omega pack: every Supreme card becomes Shiny Supreme
        if tier == "Supreme":
            if pack_key == "shiny_omega":
                tier = "Shiny Supreme"
            elif pack_key == "omega" and random.random() < 0.01:
                tier = "Shiny Supreme"

        # Force shiny variant for Shiny Omega pack
        if force_shiny:
            is_shiny_v = True

        card = {
            "id":           cd["next_id"],
            "pokemon_id":   pid,
            "species":      pname,
            "type":         ptype,
            "tier":         tier,
            "shiny_variant":is_shiny_v,
            "obtained_at":  datetime.now(timezone.utc).isoformat()[:10],
        }
        key = (pid, pname, tier)
        if key in owned_set:
            sell_val = CARD_TIERS.get(tier, CARD_TIERS["Common"])["sell"]
            auto_coins += sell_val
            card["auto_sold"] = True
        else:
            owned_set.add(key)
            cd["next_id"] += 1
            cd["cards"].append(card)
            # Always add to ,pokemon (pokédex) if this species isn't already there
            if pname not in owned_species:
                owned_species.add(pname)
                rarity = TIER_TO_RARITY.get(tier, "Common")
                _is_super_boss = (tier == "Shiny Boss")
                pk_entry = {
                    "id":                  ud["next_id"],
                    "species":             pname,
                    "pokedex_id":          pid,
                    "level":               100 if _is_super_boss else 1,
                    "ivs":                 {"hp":31,"atk":31,"def":31,"spa":31,"spd":31,"spe":31} if _is_super_boss else roll_ivs(),
                    "shiny":               False,
                    "shiny_variant":       is_shiny_v,
                    "nickname":            None,
                    "favorite":            False,
                    "moves":               [],
                    "type":                ptype,
                    "rarity":              rarity,
                    "is_dead":             False,
                    "dmg_upgrade":         5 if _is_super_boss else 0,
                    "hp_upgrade":          5 if _is_super_boss else 0,
                    "crit_chance_upgrade": 5 if _is_super_boss else 0,
                    "crit_dmg_upgrade":    5 if _is_super_boss else 0,
                    "acc_upgrade":         0,
                    "dodge_upgrade":       5 if _is_super_boss else 0,
                    "lifesteal_upgrade":   5 if _is_super_boss else 0,
                    "speed_upgrade":       4 if _is_super_boss else 0,
                    "trait":               "Boss Aura" if _is_super_boss else roll_trait_for_pokemon({"rarity":rarity,"type":ptype}),
                }
                ud["next_id"] += 1
                new_pokemon.append(pk_entry)
        opened.append(card)
    ud["pokemon"].extend(new_pokemon)
    if auto_coins > 0:
        ud["balance"] = ud.get("balance", 0) + auto_coins
    save_pokemon_data(uid, ud)
    save_cards_data(uid, cd)
    return opened, auto_coins

#  EVOLUTION HELPER
def check_and_evolve(pk: dict) -> tuple:
    """
    If pk's level has reached the evolution threshold, mutate it in-place.
    Returns (evolved: bool, old_name: str, new_name: str).
    """
    species = pk.get("species", "").lower()
    level   = pk.get("level", 1)
    evo     = POKEMON_EVOLUTIONS.get(species)
    if evo and level >= evo[0]:
        old_name    = pk["species"]
        new_species = evo[1]
        pk["species"] = new_species
        if pk.get("name") == old_name:
            pk["name"] = new_species
        return True, old_name, new_species
    return False, pk.get("species", ""), pk.get("species", "")

#  LOAD LISTS  (called on ready)
def load_lists():
    global WHITELIST_USERS, POKEMONLIST_USERS, PREMIUM_USERS
    try:
        WHITELIST_USERS   = set(load("whitelist"))
        POKEMONLIST_USERS = set(load("pokemonlist"))
        PREMIUM_USERS     = set(load("nukerlist"))
    except Exception:
        pass

