class ShopNavSelect(discord.ui.Select):
    def __init__(self, owner: discord.Member, current_page: int):
        self.owner = owner
        opts = [
            discord.SelectOption(label="🔴 Pokéballs",       value="balls",    description="Buy Pokéballs",          default=(current_page==1)),
            discord.SelectOption(label="📦 Card Packs",       value="packs",    description="Buy Card Packs",         default=(current_page==2)),
            discord.SelectOption(label="🧪 Items",            value="items",    description="Potions, Revives & more", default=(current_page==3)),
            discord.SelectOption(label="⬆️ Pokémon Upgrades", value="upgrades", description="Upgrade your Pokémon",   default=(current_page==4)),
            discord.SelectOption(label="🗺️ Maps",             value="maps",     description="Anime Map Packs & Emerald Medallion", default=(current_page==5)),
        ]
        super().__init__(placeholder="📖 Browse shop pages...", options=opts)

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.owner.id:
            return await interaction.response.send_message("Not your shop!", ephemeral=False)
        uid = str(self.owner.id)
        page = self.values[0]
        if page == "balls":
            await interaction.response.edit_message(embed=pokeshop_ball_embed(uid), view=PokeshopMainView(self.owner, 1))
        elif page == "packs":
            await interaction.response.edit_message(embed=pokeshop_pack_embed(uid), view=PokeshopMainView(self.owner, 2))
        elif page == "items":
            await interaction.response.edit_message(embed=pokeshop_items_embed(uid), view=PokeshopItemsView(self.owner))
        elif page == "upgrades":
            await interaction.response.edit_message(embed=pokeshop_upgrade_embed(uid), view=PokeshopUpgradeView(self.owner))
        elif page == "maps":
            await interaction.response.edit_message(embed=pokeshop_maps_embed(uid), view=PokeshopMapsView(self.owner))

