class ShopCustomQtyModal(discord.ui.Modal, title="Custom Quantity"):
    amount = discord.ui.TextInput(
        label="How many would you like to buy?",
        placeholder="Enter a number, e.g. 25",
        min_length=1, max_length=5,
        style=discord.TextStyle.short
    )

    def __init__(self, owner: discord.Member, item_key: str, shop_type: str):
        super().__init__()
        self.owner     = owner
        self.item_key  = item_key
        self.shop_type = shop_type  # "item" or "pack"

    async def on_submit(self, interaction: discord.Interaction):
        raw = self.amount.value.strip()
        if not raw.isdigit():
            return await interaction.response.send_message("❌ Please enter a whole number!", ephemeral=False)
        qty = int(raw)
        if qty < 1 or qty > 9999:
            return await interaction.response.send_message("❌ Quantity must be between 1 and 9,999!", ephemeral=False)
        uid = str(self.owner.id)
        ud  = get_pokemon_data(uid)
        if self.shop_type == "item":
            info  = SHOP_ITEMS[self.item_key]
            total = info["price"] * qty
            if ud.get("balance", 0) < total:
                return await interaction.response.send_message(
                    embed=discord.Embed(description=f"❌ Need **{total:,}** coins, you have **{ud.get('balance',0):,}**.", color=COLORS["error"]),
                    ephemeral=False
                )
            ud["balance"] -= total
            ud["items"][self.item_key] = ud["items"].get(self.item_key, 0) + qty
            save_pokemon_data(uid, ud)
            await interaction.response.edit_message(embed=pokeshop_items_embed(uid), view=PokeshopItemsView(self.owner))
            await interaction.followup.send(
                embed=discord.Embed(
                    description=f"✅ Bought **{qty}× {info['emoji']} {info['name']}**!\n💰 Balance: **{ud['balance']:,}**",
                    color=COLORS["success"]
                ), ephemeral=False
            )
        else:  # pack
            info  = CARD_PACKS[self.item_key]
            total = info["price"] * qty
            if ud.get("balance", 0) < total:
                return await interaction.response.send_message(
                    embed=discord.Embed(description=f"❌ Need **{total:,}** coins, you have **{ud.get('balance',0):,}**.", color=COLORS["error"]),
                    ephemeral=False
                )
            ud["balance"] -= total
            ud["packs"][self.item_key] = ud["packs"].get(self.item_key, 0) + qty
            save_pokemon_data(uid, ud)
            await interaction.response.edit_message(embed=pokeshop_pack_embed(uid), view=PokeshopMainView(self.owner, 2))
            await interaction.followup.send(
                embed=discord.Embed(
                    title=f"✅ {qty}× {info['emoji']} {info['name']} added!",
                    description=f"💰 Balance: **{ud['balance']:,}** | Use `,inventory` to open!",
                    color=COLORS["success"]
                ), ephemeral=False
            )


