class PokeshopUpgradeView(discord.ui.View):
    def __init__(self, owner: discord.Member):
        super().__init__(timeout=120)
        self.owner = owner
        self.add_item(ShopNavSelect(owner, 4))
        self.add_item(UpgradePokemonSelect(owner))

class MapPackSelect(discord.ui.Select):
    def __init__(self, owner: discord.Member):
        self.owner = owner
        uid  = str(owner.id)
        ud   = get_pokemon_data(uid)
        med  = ud.get("pokefight_medallions", 0)
        owned_maps = ud.get("owned_maps", ["starter"])
        active_map = ud.get("active_map", "starter")
        opts = []
        for key, info in MAP_PACKS.items():
            owned  = key in owned_maps
            active = (active_map == key)
            locked = info["emerald_req"] and med < 6
            if active:
                label = f"[ACTIVE] {info['name']}"
            elif owned:
                label = f"✅ {info['name']} — Equip"
            elif locked:
                label = f"🔒 {info['name']} — Need Emerald"
            else:
                label = f"{info['name']} — {info['price']:,} coins"
            opts.append(discord.SelectOption(
                label=label[:100], value=key,
                emoji=info["emoji"],
                description=info["bonus_desc"][:100],
                default=active
            ))
        super().__init__(placeholder="🗺️ Buy or equip a Map Pack...", options=opts[:25], row=1)

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.owner.id:
            return await interaction.response.send_message("Not your shop!", ephemeral=False)
        uid  = str(self.owner.id)
        ud   = get_pokemon_data(uid)
        med  = ud.get("pokefight_medallions", 0)
        bal  = ud.get("balance", 0)
        owned_maps = ud.get("owned_maps", ["starter"])
        key  = self.values[0]
        info = MAP_PACKS[key]

        if ud.get("active_map", "starter") == key:
            return await interaction.response.send_message(
                embed=discord.Embed(description=f"✅ **{info['name']}** is already your active map!", color=COLORS["success"]),
                ephemeral=False
            )
        if key in owned_maps:
            ud["active_map"] = key
            save_pokemon_data(uid, ud)
            await interaction.response.edit_message(embed=pokeshop_maps_embed(uid), view=PokeshopMapsView(self.owner))
            return await interaction.followup.send(
                embed=discord.Embed(description=f"✅ Equipped **{info['emoji']} {info['name']}**!\n{info['bonus_desc']}", color=COLORS["success"]),
                ephemeral=False
            )
        if info["emerald_req"] and med < 6:
            return await interaction.response.send_message(
                embed=discord.Embed(
                    description=f"🔒 **{info['name']}** requires the **💚 Emerald Medallion**!\nBuy it below to unlock all anime map packs.",
                    color=COLORS["error"]
                ), ephemeral=False
            )
        if info["price"] > 0 and bal < info["price"]:
            return await interaction.response.send_message(
                embed=discord.Embed(
                    description=f"❌ You need **{info['price']:,} coins** for **{info['name']}**.\nYour balance: **{bal:,}** coins.",
                    color=COLORS["error"]
                ), ephemeral=False
            )
        if info["price"] > 0:
            ud["balance"] -= info["price"]
        if key not in owned_maps:
            owned_maps.append(key)
        ud["owned_maps"] = owned_maps
        ud["active_map"] = key
        save_pokemon_data(uid, ud)
        await interaction.response.edit_message(embed=pokeshop_maps_embed(uid), view=PokeshopMapsView(self.owner))
        cost_txt = f"\n💰 Remaining balance: **{ud['balance']:,}** coins" if info["price"] > 0 else ""
        await interaction.followup.send(
            embed=discord.Embed(
                title=f"{info['emoji']} Map Unlocked!",
                description=f"You bought **{info['name']}**!\n\n✅ {info['bonus_desc']}{cost_txt}",
                color=0x00C853
            ), ephemeral=False
        )

class PokeshopMapsView(discord.ui.View):
    def __init__(self, owner: discord.Member):
        super().__init__(timeout=120)
        self.owner = owner
        self.add_item(ShopNavSelect(owner, 5))
        self.add_item(MapPackSelect(owner))

    @discord.ui.button(label="💚 Buy Emerald Medallion — 1,000,000 coins", style=discord.ButtonStyle.success, row=2)
    async def buy_emerald(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != self.owner.id:
            return await interaction.response.send_message("Not your shop!", ephemeral=False)
        uid = str(self.owner.id)
        ud  = get_pokemon_data(uid)
        med    = ud.get("pokefight_medallions", 0)
        total_w= ud.get("pokefight_total_waves", 0)
        bal    = ud.get("balance", 0)

        if med >= 6:
            return await interaction.response.send_message(
                embed=discord.Embed(description="✅ You already have the **Emerald Medallion**!", color=COLORS["success"]),
                ephemeral=False
            )
        if med < EMERALD_MEDAL_REQ:
            return await interaction.response.send_message(
                embed=discord.Embed(
                    description=f"❌ You need **Diamond Medallion** or higher.\nYou have: {MEDALLION_EMOJIS.get(med,'⬛')} **{MEDALLION_NAMES.get(med,'Unranked')}**",
                    color=COLORS["error"]
                ), ephemeral=False
            )
        if total_w < EMERALD_WAVE_REQ:
            return await interaction.response.send_message(
                embed=discord.Embed(
                    description=f"❌ You need **{EMERALD_WAVE_REQ} total waves** completed.\nYou have: **{total_w:,}**",
                    color=COLORS["error"]
                ), ephemeral=False
            )
        if bal < EMERALD_PRICE:
            return await interaction.response.send_message(
                embed=discord.Embed(
                    description=f"❌ You need **1,000,000 PokéCoins**.\nYou have: **{bal:,}**",
                    color=COLORS["error"]
                ), ephemeral=False
            )

        ud["balance"] -= EMERALD_PRICE
        ud["pokefight_medallions"] = 6
        ud["pokefight_current_waves"] = 0
        ud["pokefight_boss_ready"] = False
        save_pokemon_data(uid, ud)

        await interaction.response.edit_message(embed=pokeshop_maps_embed(uid), view=PokeshopMapsView(self.owner))
        await interaction.followup.send(
            embed=discord.Embed(
                title="💚 Emerald Medallion Unlocked!",
                description=(
                    "You have ascended to the **Emerald Tier** — the highest rank!\n\n"
                    "🌊 **Infinite waves** — no boss needed to progress\n"
                    "💰 **5× coin boost** on all fight rewards\n"
                    "🎁 **Massive pack drop rates** — up to 1% Boss Pack per win\n"
                    "💚 **Apex Boss** appears every 100 waves\n"
                    "🗺️ **All Anime Map Packs** unlocked for purchase!\n\n"
                    f"💳 Remaining balance: **{ud['balance']:,}** PokéCoins"
                ),
                color=0x00C853
            ), ephemeral=False
        )


class UpgradePokemonSelect(discord.ui.Select):
    def __init__(self, owner: discord.Member):
        self.owner = owner
        uid  = str(owner.id)
        ud   = get_pokemon_data(uid)
        opts = []
        for pk in ud["pokemon"][:25]:
            rarity = pk.get("rarity", "Common")
            shiny_v= "✨" if pk.get("shiny_variant") else ""
            dead   = "💀" if pk.get("is_dead") else ""
            label  = f"#{pk['id']} {dead}{shiny_v}{pk['species'].capitalize()} Lv.{pk.get('level',1)} [{rarity}]"
            opts.append(discord.SelectOption(
                label=label[:100], value=str(pk["id"]),
                description=f"DMG Lv:{pk.get('dmg_upgrade',0)} | HP Lv:{pk.get('hp_upgrade',0)} | CC:{int(CRIT_CHANCE_VALUES[min(pk.get('crit_chance_upgrade',0),5)]*100)}%",
                emoji=RARITY_EMOJI.get(rarity,"⚪")
            ))
        if not opts:
            opts.append(discord.SelectOption(label="No Pokémon yet!", value="none"))
        super().__init__(placeholder="⬆️ Choose a Pokémon to upgrade...", options=opts, row=1)

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.owner.id:
            return await interaction.response.send_message("Not yours!", ephemeral=False)
        if self.values[0] == "none":
            return await interaction.response.send_message("No Pokémon to upgrade!", ephemeral=False)
        pid = int(self.values[0])
        uid = str(self.owner.id)
        ud  = get_pokemon_data(uid)
        # Find specifically the chosen pokemon by ID
        pk  = next((p for p in ud["pokemon"] if p["id"] == pid), None)
        if not pk:
            return await interaction.response.send_message("Pokémon not found!", ephemeral=False)
        await interaction.response.edit_message(
            embed=upgrade_stats_embed(pk, ud.get("balance", 0)),
            view=UpgradeTypeView(self.owner, pid)
        )

def upgrade_stats_embed(pk: dict, balance: int) -> discord.Embed:
    rarity = pk.get("rarity", "Common")
    dmg_lv = pk.get("dmg_upgrade", 0)
    hp_lv  = pk.get("hp_upgrade", 0)
    cc_lv  = pk.get("crit_chance_upgrade", 0)
    cd_lv  = pk.get("crit_dmg_upgrade", 0)
    e = discord.Embed(
        title=f"⬆️ Upgrade: {pk['species'].capitalize()} (ID #{pk['id']})",
        color=RARITY_COLOR.get(rarity, 0xFFD700)
    )
    e.description = (
        f"**Rarity:** {RARITY_EMOJI.get(rarity,'⚪')} {rarity}\n"
        f"**Balance:** {balance:,} coins\n"
        "━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
        "⚠️ **Only this Pokémon will be upgraded!**\n"
    )
    def cost_str(lv, max_lv):
        if lv >= max_lv: return "**MAX**"
        return f"{get_upgrade_cost(rarity, lv):,} coins"
    acc_lv  = pk.get("acc_upgrade", 0)
    dod_lv  = pk.get("dodge_upgrade", 0)
    ls_lv   = pk.get("lifesteal_upgrade", 0)
    sp_lv   = pk.get("speed_upgrade", 0)
    is_godly = rarity in ("Godly","Supreme")
    e.add_field(name="⚔️ Damage",
        value=f"Level **{dmg_lv}/5** → `{DMG_UPGRADE_MULTS[min(dmg_lv,5)]}x`\nNext: {cost_str(dmg_lv,5)}", inline=True)
    e.add_field(name="❤️ HP",
        value=f"Level **{hp_lv}/5** → `{HP_UPGRADE_MULTS[min(hp_lv,5)]}x`\nNext: {cost_str(hp_lv,5)}", inline=True)
    e.add_field(name="🎯 Crit Chance",
        value=f"Level **{cc_lv}/5** → `{int(CRIT_CHANCE_VALUES[min(cc_lv,5)]*100)}%`\nNext: {cost_str(cc_lv,5)}", inline=True)
    e.add_field(name="💥 Crit Damage",
        value=f"Level **{cd_lv}/10** → `{int(CRIT_DMG_VALUES[min(cd_lv,10)]*100)}%`\nNext: {cost_str(cd_lv,10)}", inline=True)
    if is_godly:
        def acc_cost_str(lv):
            if lv >= 9: return "**MAX**"
            return f"{get_acc_upgrade_cost(rarity, lv):,} coins"
        e.add_field(name="🎯 Accuracy *(Godly/Supreme)*",
            value=f"Level **{acc_lv}/9** → `{int(ACC_UPGRADE_VALUES[min(acc_lv,9)]*100)}%`\nNext: {acc_cost_str(acc_lv)}", inline=True)
    e.add_field(name="🌀 Dodge Chance",
        value=f"Level **{dod_lv}/5** → `{int(DODGE_CHANCE_VALUES[min(dod_lv,5)]*100)}%`\nNext: {cost_str(dod_lv,5)}", inline=True)
    e.add_field(name="💉 Lifesteal",
        value=f"Level **{ls_lv}/5** → `{int(LIFESTEAL_VALUES[min(ls_lv,5)]*100)}%`\nNext: {cost_str(ls_lv,5)}", inline=True)
    e.add_field(name="⚡ Speed Priority",
        value=f"Level **{sp_lv}/4** → `{int(SPEED_PRIORITY_VALUES[min(sp_lv,4)]*100)}%`\nNext: {cost_str(sp_lv,4)}", inline=True)
    pktrait = pk.get("trait","")
    tinfo   = POKEMON_TRAITS.get(pktrait,{})
    if tinfo:
        e.add_field(name=f"{tinfo.get('emoji','✦')} Trait: {pktrait}",
            value=tinfo.get("desc",""), inline=False)
    return e

class UpgradeTypeView(discord.ui.View):
    def __init__(self, owner: discord.Member, pokemon_id: int):
        super().__init__(timeout=90)
        self.add_item(ShopNavSelect(owner, 4))
        self.add_item(UpgradeTypeSelect(owner, pokemon_id))

class UpgradeTypeSelect(discord.ui.Select):
    def __init__(self, owner: discord.Member, pokemon_id: int):
        self.owner = owner; self.pokemon_id = pokemon_id
        uid = str(owner.id)
        ud  = get_pokemon_data(uid)
        pk  = next((p for p in ud["pokemon"] if p["id"] == pokemon_id), None)
        rarity = pk.get("rarity","Common") if pk else "Common"
        bal    = ud.get("balance",0)
        opts   = []
        if pk:
            dmg_lv= pk.get("dmg_upgrade",0)
            hp_lv = pk.get("hp_upgrade",0)
            cc_lv = pk.get("crit_chance_upgrade",0)
            cd_lv = pk.get("crit_dmg_upgrade",0)
            if dmg_lv < 5:
                cost = get_upgrade_cost(rarity, dmg_lv)
                opts.append(discord.SelectOption(label=f"⚔️ Damage (Lv {dmg_lv}→{dmg_lv+1}) — {cost:,} coins", value="dmg",
                    description=f"{DMG_UPGRADE_MULTS[dmg_lv]}x → {DMG_UPGRADE_MULTS[dmg_lv+1]}x", emoji="⚔️"))
            if hp_lv < 5:
                cost = get_upgrade_cost(rarity, hp_lv)
                opts.append(discord.SelectOption(label=f"❤️ HP (Lv {hp_lv}→{hp_lv+1}) — {cost:,} coins", value="hp",
                    description=f"{HP_UPGRADE_MULTS[hp_lv]}x → {HP_UPGRADE_MULTS[hp_lv+1]}x", emoji="❤️"))
            if cc_lv < 5:
                cost = get_upgrade_cost(rarity, cc_lv)
                opts.append(discord.SelectOption(label=f"🎯 Crit Chance (Lv {cc_lv}→{cc_lv+1}) — {cost:,} coins", value="crit_chance",
                    description=f"{int(CRIT_CHANCE_VALUES[cc_lv]*100)}% → {int(CRIT_CHANCE_VALUES[cc_lv+1]*100)}%", emoji="🎯"))
            if cd_lv < 10:
                cost = get_upgrade_cost(rarity, cd_lv)
                opts.append(discord.SelectOption(label=f"💥 Crit Damage (Lv {cd_lv}→{cd_lv+1}) — {cost:,} coins", value="crit_dmg",
                    description=f"{int(CRIT_DMG_VALUES[cd_lv]*100)}% → {int(CRIT_DMG_VALUES[cd_lv+1]*100)}%", emoji="💥"))
            # New upgrades
            dod_lv = pk.get("dodge_upgrade", 0)
            ls_lv  = pk.get("lifesteal_upgrade", 0)
            sp_lv  = pk.get("speed_upgrade", 0)
            acc_lv = pk.get("acc_upgrade", 0)
            is_godly_sup = rarity in ("Godly","Supreme")
            if is_godly_sup and acc_lv < 9:
                cost = get_acc_upgrade_cost(rarity, acc_lv)
                opts.append(discord.SelectOption(label=f"🎯 Accuracy (Lv {acc_lv}→{acc_lv+1}) — {cost:,} coins", value="acc",
                    description=f"{int(ACC_UPGRADE_VALUES[acc_lv]*100)}% → {int(ACC_UPGRADE_VALUES[acc_lv+1]*100)}%", emoji="🎯"))
            if dod_lv < 5:
                cost = get_upgrade_cost(rarity, dod_lv)
                opts.append(discord.SelectOption(label=f"🌀 Dodge (Lv {dod_lv}→{dod_lv+1}) — {cost:,} coins", value="dodge",
                    description=f"{int(DODGE_CHANCE_VALUES[dod_lv]*100)}% → {int(DODGE_CHANCE_VALUES[dod_lv+1]*100)}%", emoji="🌀"))
            if ls_lv < 5:
                cost = get_upgrade_cost(rarity, ls_lv)
                opts.append(discord.SelectOption(label=f"💉 Lifesteal (Lv {ls_lv}→{ls_lv+1}) — {cost:,} coins", value="lifesteal",
                    description=f"{int(LIFESTEAL_VALUES[ls_lv]*100)}% → {int(LIFESTEAL_VALUES[ls_lv+1]*100)}%", emoji="💉"))
            if sp_lv < 4:
                cost = get_upgrade_cost(rarity, sp_lv)
                opts.append(discord.SelectOption(label=f"⚡ Speed (Lv {sp_lv}→{sp_lv+1}) — {cost:,} coins", value="speed",
                    description=f"{int(SPEED_PRIORITY_VALUES[sp_lv]*100)}% → {int(SPEED_PRIORITY_VALUES[sp_lv+1]*100)}%", emoji="⚡"))
        # Discord Select max 25 options
        opts = opts[:23]
        if not opts:
            opts.append(discord.SelectOption(label="All upgrades MAXED!", value="none", emoji="🏆"))
        opts.append(discord.SelectOption(label="← Back to Pokémon list", value="back", emoji="🔙"))
        super().__init__(placeholder="🔧 Select an upgrade...", options=opts, row=1)

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.owner.id:
            return await interaction.response.send_message("Not yours!", ephemeral=False)
        val = self.values[0]
        if val == "none":
            return await interaction.response.send_message("All upgrades are maxed!", ephemeral=False)
        if val == "back":
            return await interaction.response.edit_message(
                embed=pokeshop_upgrade_embed(str(self.owner.id)), view=PokeshopUpgradeView(self.owner)
            )
        uid = str(self.owner.id)
        ud  = get_pokemon_data(uid)
        pk  = next((p for p in ud["pokemon"] if p["id"] == self.pokemon_id), None)
        if not pk:
            return await interaction.response.send_message("Pokémon not found!", ephemeral=False)
        rarity = pk.get("rarity","Common")
        field_map = {
            "dmg":      ("dmg_upgrade",      5,  lambda r,lv: get_upgrade_cost(r, lv)),
            "hp":       ("hp_upgrade",       5,  lambda r,lv: get_upgrade_cost(r, lv)),
            "crit_chance":("crit_chance_upgrade",5, lambda r,lv: get_upgrade_cost(r, lv)),
            "crit_dmg": ("crit_dmg_upgrade", 10, lambda r,lv: get_upgrade_cost(r, lv)),
            "acc":      ("acc_upgrade",      9,  lambda r,lv: get_acc_upgrade_cost(r, lv)),
            "dodge":    ("dodge_upgrade",    5,  lambda r,lv: get_upgrade_cost(r, lv)),
            "lifesteal":("lifesteal_upgrade",5,  lambda r,lv: get_upgrade_cost(r, lv)),
            "speed":    ("speed_upgrade",    4,  lambda r,lv: get_upgrade_cost(r, lv)),
        }
        if val not in field_map:
            return await interaction.response.send_message("Unknown upgrade type!", ephemeral=False)
        field, max_lv, cost_fn = field_map[val]
        cur_lv = pk.get(field, 0)
        if cur_lv >= max_lv:
            return await interaction.response.send_message("Already at max level!", ephemeral=False)
        cost = cost_fn(rarity, cur_lv)
        if ud.get("balance",0) < cost:
            return await interaction.response.send_message(
                embed=discord.Embed(description=f"❌ Need **{cost:,}** coins, have **{ud.get('balance',0):,}**.", color=COLORS["error"]),
                ephemeral=False
            )
        ud["balance"] -= cost
        pk[field] = cur_lv + 1
        save_pokemon_data(uid, ud)
        name_map = {"dmg":"Damage","hp":"HP","crit_chance":"Crit Chance","crit_dmg":"Crit Damage",
                    "acc":"Accuracy","dodge":"Dodge","lifesteal":"Lifesteal","speed":"Speed Priority"}
        await interaction.response.edit_message(
            embed=upgrade_stats_embed(pk, ud["balance"]),
            view=UpgradeTypeView(self.owner, self.pokemon_id)
        )
        await interaction.followup.send(
            embed=discord.Embed(
                description=f"✅ **{pk['species'].capitalize()}** (ID #{pk['id']})'s **{name_map[val]}** upgraded to Level {cur_lv+1}!\n💰 Spent **{cost:,}** | Balance: **{ud['balance']:,}**",
                color=COLORS["success"]
            ), ephemeral=False
        )

#  VIEW — INVENTORY  (3 pages)
class InventoryNavSelect(discord.ui.Select):
    def __init__(self, owner: discord.Member, page: int):
        self.owner = owner
        opts = [
            discord.SelectOption(label="🐾 Pokémon", value="pokemon", description="Your Pokémon collection", default=(page==1)),
            discord.SelectOption(label="📦 Packs",   value="packs",   description="Your card packs",         default=(page==2)),
            discord.SelectOption(label="🧪 Items",    value="items",   description="Potions & boosts",        default=(page==3)),
        ]
        super().__init__(placeholder="📋 Switch inventory page...", options=opts)

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.owner.id:
            return await interaction.response.send_message("Not your inventory!", ephemeral=False)
        uid = str(self.owner.id)
        page = self.values[0]
        if page == "pokemon":
            await interaction.response.edit_message(embed=inv_pokemon_embed(uid, self.owner, 0), view=InventoryPokemonView(self.owner, 0))
        elif page == "packs":
            await interaction.response.edit_message(embed=inv_packs_embed(uid, self.owner), view=InventoryPacksView(self.owner))
        elif page == "items":
            await interaction.response.edit_message(embed=inv_items_embed(uid, self.owner), view=InventoryItemsView(self.owner))

def inv_packs_embed(uid: str, owner: discord.Member) -> discord.Embed:
    ud    = get_pokemon_data(uid)
    packs = ud.get("packs", {})
    act   = ud.get("active_map", "starter")
    e = discord.Embed(
        title=f"📦 {owner.display_name}'s Packs",
        description="Select a pack from the dropdown to open it!\n*(Map packs require your active map to match)*\n━━━━━━━━━━━━━━━━━━━━━━━━━━",
        color=0xFF9800
    )
    any_owned = False
    for pk_key, info in CARD_PACKS.items():
        cnt = packs.get(pk_key, 0)
        if cnt > 0:
            e.add_field(name=f"{info['emoji']} {info['name']}", value=f"Owned: **{cnt}**\n{info['desc']}", inline=True)
            any_owned = True
    for pack_key, map_key in MAP_PACK_KEYS.items():
        cnt = packs.get(pack_key, 0)
        if cnt > 0:
            info = MAP_PACK_CONTENTS.get(map_key, MAP_PACK_CONTENTS["starter"])
            lock = "✅ Active — open away!" if act == map_key else "🔒 Switch to this map to open"
            e.add_field(
                name=f"🗺️ {info['name']}",
                value=f"Owned: **{cnt}**\nAnime Pokémon + coins + balls\n{lock}",
                inline=True
            )
            any_owned = True
    if not any_owned:
        e.description += "\n\n🚫 You don't own any packs! Kill bosses or buy map packs."
    e.set_footer(text="Page 2/3 — Inventory  •  Map packs require active map to open")
    return e

def inv_items_embed(uid: str, owner: discord.Member) -> discord.Embed:
    ud    = get_pokemon_data(uid)
    items = ud.get("items", {})
    balls = ud.get("pokeballs", {})
    e = discord.Embed(
        title=f"🧪 {owner.display_name}'s Items & Balls",
        description="Select an item from the dropdown to use it!\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
        color=0x00BCD4
    )
    # Show active coin boost if any
    expire = ACTIVE_COIN_BOOSTS.get(uid, 0)
    if time.time() < expire:
        remaining = int(expire - time.time())
        e.description += f"\n\n💹 **Coin Boost active!** +50% coins for **{remaining}s** more."
    # ── Pokéballs section ────────────────────────────────────
    balls_txt = "  ".join(
        f"{POKEBALL_EMOJI.get(b,'🔴')} **{b.capitalize()}** ×{cnt}"
        for b, cnt in balls.items() if cnt > 0
    ) or "None — buy at `,pokeshop`"
    e.add_field(name="🎒 Pokéballs", value=balls_txt, inline=False)
    # ── Items section ────────────────────────────────────────
    any_owned = False
    for key, info in SHOP_ITEMS.items():
        cnt = items.get(key, 0)
        if cnt > 0:
            e.add_field(name=f"{info['emoji']} {info['name']}", value=f"Owned: **{cnt}**\n{info['desc']}", inline=True)
            any_owned = True
    if not any_owned:
        e.add_field(name="🚫 No Items", value="Buy some at `,pokeshop` → Items.", inline=False)
    e.set_footer(text="Page 3/3 — Inventory  •  Use dropdown to use an item")
    return e

def inv_pokemon_embed(uid: str, owner: discord.Member, page: int) -> discord.Embed:
    ud       = get_pokemon_data(uid)
    pklist   = ud.get("pokemon", [])
    per_page = 10
    start    = page * per_page
    chunk    = pklist[start:start+per_page]
    total_p  = math.ceil(len(pklist) / per_page) if pklist else 1
    e = discord.Embed(title=f"🐾 {owner.display_name}'s Pokémon", color=COLORS["pokemon"])
    lines = []
    for pk in chunk:
        shiny_v = "✨" if pk.get("shiny_variant") else ""
        shiny   = "🌟" if pk.get("shiny") else ""
        dead    = "💀" if pk.get("is_dead") else ""
        fav     = "⭐" if pk.get("favorite") else ""
        rarity  = pk.get("rarity","Common")
        ivpct   = iv_percentage(pk.get("ivs", roll_ivs()))
        lines.append(
            f"`#{pk['id']:>4}` {dead}{fav}{shiny_v}{shiny}{RARITY_EMOJI.get(rarity,'⚪')} "
            f"**{pk['species'].capitalize()}** Lv.**{pk.get('level',1)}** IV:{ivpct}%"
        )
    e.description = "\n".join(lines) if lines else "No Pokémon! Use `,start` to begin."
    e.set_footer(text=f"Page {page+1}/{total_p} | {len(pklist)} total | Page 1/3 — Inventory")
    return e

class InventoryPacksView(discord.ui.View):
    def __init__(self, owner: discord.Member):
        super().__init__(timeout=120)
        self.owner = owner
        self.add_item(InventoryNavSelect(owner, 2))
        uid   = str(owner.id)
        ud    = get_pokemon_data(uid)
        packs = ud.get("packs", {})
        has_card = any(packs.get(k, 0) > 0 for k in CARD_PACKS)
        has_map  = any(packs.get(pk, 0) > 0 for pk in MAP_PACK_KEYS)
        if has_card or has_map:
            self.add_item(OpenPackSelect(owner))

PACK_COLORS = {
    "basic": 0x9E9E9E, "rare": 0x2196F3, "epic": 0x9C27B0,
    "legendary": 0xFFD700, "master": 0xFF4500, "godly": 0xFF1493,
    "omega": 0x00BCD4, "shiny_omega": 0xFF69B4,
    "boss": 0xB22222, "super_boss": 0xFF0000,
}

class OpenPackSelect(discord.ui.Select):
    def __init__(self, owner: discord.Member):
        self.owner = owner
        uid   = str(owner.id)
        ud    = get_pokemon_data(uid)
        packs = ud.get("packs", {})
        opts  = []
        act = ud.get("active_map", "starter")
        for pk_key, info in CARD_PACKS.items():
            cnt = packs.get(pk_key, 0)
            if cnt > 0:
                opts.append(discord.SelectOption(
                    label=f"{info['name']}  ×{cnt}",
                    value=pk_key, emoji=info["emoji"],
                    description=f"{info['desc']}  •  {cnt} owned"
                ))
        for pack_key, map_key in MAP_PACK_KEYS.items():
            cnt = packs.get(pack_key, 0)
            if cnt > 0:
                minfo    = MAP_PACK_CONTENTS.get(map_key, MAP_PACK_CONTENTS["starter"])
                can_open = (act == map_key)
                mdesc    = f"Anime Pokémon + loot  •  {cnt} owned" + ("" if can_open else "  🔒 Switch map first")
                opts.append(discord.SelectOption(
                    label=f"{minfo['name']}  ×{cnt}",
                    value=pack_key, emoji="🗺️",
                    description=mdesc[:100]
                ))
        if not opts:
            opts.append(discord.SelectOption(label="No packs to open", value="none"))
        super().__init__(placeholder="📦 Choose a pack to open...", options=opts[:25], row=1)

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.owner.id:
            return await interaction.response.send_message("Not your inventory!", ephemeral=False)
        if self.values[0] == "none":
            return await interaction.response.send_message("No packs to open!", ephemeral=False)
        pk_key = self.values[0]
        uid    = str(self.owner.id)
        ud     = get_pokemon_data(uid)
        owned  = ud["packs"].get(pk_key, 0)
        if owned < 1:
            return await interaction.response.send_message(
                embed=discord.Embed(description="❌ You don't have that pack anymore!", color=COLORS["error"]),
                ephemeral=False
            )
        # Map pack opening
        if pk_key in MAP_PACK_KEYS:
            map_key = MAP_PACK_KEYS[pk_key]
            result  = open_map_pack(uid, map_key)
            if result.get("error") == "wrong_map":
                act_name = MAP_PACKS.get(ud.get("active_map","starter"), {}).get("name","Starter Map")
                return await interaction.response.send_message(
                    embed=discord.Embed(
                        title="🔒 Wrong Map!",
                        description=(
                            f"You must be on the **{MAP_PACK_CONTENTS[map_key]['name'].replace(' Pack','')} Map** to open this pack!\n\n"
                            f"Your active map: **{act_name}**\n"
                            "Go to ,pokeshop > Maps and switch your active map first."
                        ),
                        color=COLORS["error"]
                    ), ephemeral=False
                )
            if result.get("error") == "no_packs":
                return await interaction.response.send_message(
                    embed=discord.Embed(description="❌ You don't have that map pack!", color=COLORS["error"]),
                    ephemeral=False
                )
            minfo = MAP_PACK_CONTENTS[map_key]
            e = discord.Embed(
                title=f"🗺️ {minfo['name']} Opened!",
                description=f"*{result['flavor']}*",
                color=0x00C853
            )
            e.add_field(name="💰 Coins", value=f"+**{result['coins']:,}**", inline=True)
            if result["pokeballs"]:
                e.add_field(name="🎯 Pokéballs", value="  ".join(f"{b.capitalize()} ×{q}" for b,q in result["pokeballs"].items()), inline=True)
            if result["items"]:
                e.add_field(name="🧪 Items", value="  ".join(f"{k.replace('_', ' ').title()} ×{v}" for k,v in result["items"].items()), inline=True)
            if result["pokemon"]:
                lines = []
                for pk in result["pokemon"]:
                    shiny = "🌟 SHINY! " if pk.get("shiny") else ""
                    lines.append(f"{shiny}**{pk['species']}** — {pk['rarity']} · Lv.{pk['level']} · HP {pk['hp']} ATK {pk['attack']} DEF {pk['defense']} SPD {pk['speed']}")
                e.add_field(name=f"🐾 Anime Pokémon (×{len(result['pokemon'])})", value="\n".join(lines), inline=False)
            e.set_footer(text="Anime Pokémon are map-exclusive — check your ,inv!")
            await interaction.response.edit_message(embed=inv_packs_embed(uid, self.owner), view=InventoryPacksView(self.owner))
            return await interaction.followup.send(embed=e, ephemeral=False)
        # Regular card pack
        info = CARD_PACKS[pk_key]
        e = discord.Embed(
            title=f"{info['emoji']}  How many {info['name']}s to open?",
            description=(
                f"You own **{owned}×** {info['emoji']} **{info['name']}**\n"
                f"*{info['desc']}*\n\n"
                f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
                f"Select a quantity below to open:"
            ),
            color=PACK_COLORS.get(pk_key, 0xFF9800),
        )
        e.set_footer(text="Coolbot  •  Inventory  •  Greyed-out = not enough packs")
        await interaction.response.edit_message(embed=e, view=PackQuantityView(self.owner, pk_key, owned))


def _build_pack_open_result(owner: discord.Member, pack_key: str, all_cards: list, total_auto_coins: int, pack_count: int) -> discord.Embed:
    info       = CARD_PACKS[pack_key]
    pack_color = PACK_COLORS.get(pack_key, 0xFF9800)
    new_cards  = [c for c in all_cards if not c.get("auto_sold")]
    auto_sold  = [c for c in all_cards if c.get("auto_sold")]

    TIER_ORDER_DISPLAY = [
        "Shiny Boss","Boss","Shiny Supreme","Supreme",
        "Godly","Secret","Legendary","Epic","Rare","Uncommon","Common",
    ]
    # find best pull for banner line
    best_card  = None
    for tier in TIER_ORDER_DISPLAY:
        found = next((c for c in new_cards if c["tier"] == tier), None)
        if found: best_card = found; break
    if best_card is None and new_cards:
        best_card = new_cards[0]

    # ── embed ──────────────────────────────────────────────────
    e = discord.Embed(color=pack_color)
    e.set_author(name=f"{info['emoji']}  {owner.display_name} opened {pack_count:,}× {info['name']}")

    if pack_count == 1:
        # ── Single pack: card grid ─────────────────────────────
        if best_card:
            ti      = CARD_TIERS.get(best_card["tier"], CARD_TIERS["Common"])
            shn_tag = " ✨ **SHINY VARIANT**" if best_card.get("shiny_variant") else ""
            e.title = f"✦  Best Pull:  {ti['emoji']} {best_card['species'].capitalize()} — {best_card['tier']}{shn_tag}"

        # Cards in inline fields (up to 24)
        for card in new_cards[:24]:
            ti      = CARD_TIERS.get(card["tier"], CARD_TIERS["Common"])
            shn     = " ✨" if card.get("shiny_variant") else ""
            t_emoji = TYPE_EMOJI.get(card["type"], "⭐")
            e.add_field(
                name  = f"{ti['emoji']}  {card['species'].capitalize()}{shn}",
                value = f"```{card['tier']}```{t_emoji} {card['type'].capitalize()}\n`#{card['id']}`",
                inline= True,
            )

        # Overflow notice
        if len(new_cards) > 24:
            e.add_field(name=f"+ {len(new_cards)-24} more cards", value="*(see ,inventory)*", inline=False)

        # Auto-sold block
        if auto_sold:
            sold_names = " · ".join(f"{c['species'].capitalize()} ({c['tier']})" for c in auto_sold[:6])
            if len(auto_sold) > 6: sold_names += f"  … +{len(auto_sold)-6} more"
            e.add_field(
                name  = f"♻️  Auto-Sold  ·  +{total_auto_coins:,} coins",
                value = sold_names,
                inline= False,
            )

    else:
        # ── Multi-pack: tier breakdown ────────────────────────
        if best_card:
            ti      = CARD_TIERS.get(best_card["tier"], CARD_TIERS["Common"])
            shn_tag = " ✨ Shiny!" if best_card.get("shiny_variant") else ""
            e.title = f"✦  Best Pull:  {ti['emoji']} {best_card['species'].capitalize()} — {best_card['tier']}{shn_tag}"

        from collections import Counter
        tier_counts  = Counter(c["tier"] for c in new_cards)
        shiny_count  = sum(1 for c in new_cards if c.get("shiny_variant"))
        total_new    = len(new_cards)

        # Build a visual bar breakdown
        bar_lines = []
        BAR_FULL  = "█"; BAR_EMPTY = "░"; BAR_LEN = 12
        for tier in TIER_ORDER_DISPLAY:
            cnt = tier_counts.get(tier, 0)
            if not cnt: continue
            ti   = CARD_TIERS.get(tier, CARD_TIERS["Common"])
            pct  = cnt / max(total_new, 1)
            fill = round(pct * BAR_LEN)
            bar  = BAR_FULL * fill + BAR_EMPTY * (BAR_LEN - fill)
            bar_lines.append(f"{ti['emoji']} **{tier:<14}** `{bar}` {cnt:>3}")
        if shiny_count:
            bar_lines.append(f"✨ **Shiny Variants    ** `{'█'*min(shiny_count,12):<12}` {shiny_count:>3}")

        e.description = "\n".join(bar_lines) if bar_lines else "*No new cards*"

        # Summary fields
        e.add_field(
            name  = "📦  Packs Opened",
            value = f"**{pack_count:,}** packs\n**{total_new:,}** new cards",
            inline= True,
        )
        if auto_sold:
            e.add_field(
                name  = "♻️  Auto-Sold",
                value = f"**{len(auto_sold):,}** duplicate(s)\n+**{total_auto_coins:,}** coins",
                inline= True,
            )
        # Rarest pulls highlight (top 5)
        highlights = []
        for tier in TIER_ORDER_DISPLAY:
            for c in new_cards:
                if c["tier"] == tier:
                    ti  = CARD_TIERS.get(tier, CARD_TIERS["Common"])
                    shn = " ✨" if c.get("shiny_variant") else ""
                    highlights.append(f"{ti['emoji']} {c['species'].capitalize()}{shn}")
                    if len(highlights) >= 5: break
            if len(highlights) >= 5: break
        if highlights:
            e.add_field(
                name  = "🏆  Top Pulls",
                value = "\n".join(highlights),
                inline= True,
            )

    e.set_footer(text=f"Coolbot  ·  {owner.display_name}'s Collection  ·  {pack_count:,}× {info['name']}")
    return e

class PackQuantityButton(discord.ui.Button):
    def __init__(self, owner: discord.Member, pack_key: str, qty: int, owned: int, label: str, style: discord.ButtonStyle, row: int = 0):
        self.owner    = owner
        self.pack_key = pack_key
        self.qty      = qty  # -1 = open all
        enough        = owned >= qty if qty > 0 else owned >= 1
        super().__init__(label=label, style=style, disabled=not enough, row=row)

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.owner.id:
            return await interaction.response.send_message("Not your inventory!", ephemeral=False)
        uid = str(self.owner.id)
        if uid in _OPENING_PACKS:
            return await interaction.response.send_message(
                embed=discord.Embed(description="⏳ Already opening packs, please wait!", color=COLORS["warn"]),
                ephemeral=False
            )
        _OPENING_PACKS.add(uid)
        try:
            await interaction.response.defer()
            ud    = get_pokemon_data(uid)
            owned = ud["packs"].get(self.pack_key, 0)
            amount = owned if self.qty == -1 else self.qty
            if owned < amount or amount < 1:
                _OPENING_PACKS.discard(uid)
                return await interaction.followup.send(
                    embed=discord.Embed(description="❌ You don't have enough packs!", color=COLORS["error"]),
                    ephemeral=False
                )
            ud["packs"][self.pack_key] -= amount
            save_pokemon_data(uid, ud)
            all_cards        = []
            total_auto_coins = 0
            for _ in range(amount):
                cards, coins = open_card_pack(uid, self.pack_key)
                all_cards.extend(cards)
                total_auto_coins += coins

            # ── Pack roulette animation ───────────────────────────────
            info       = CARD_PACKS[self.pack_key]
            pack_color = PACK_COLORS.get(self.pack_key, 0xFF9800)
            # Roulette wheel emojis cycle through all rarity tiers
            ROULETTE_WHEEL = [
                "⚪","⚪","🟢","🟢","🔵","🔵","🟣","🟣",
                "🟡","🟡","🟠","❤️","🌟","💠","✨","❓",
            ]
            num_slots = min(info["cards"], 6)

            #  PACK OPENING  —  Clean Premium UI
            info       = CARD_PACKS[self.pack_key]
            pack_color = PACK_COLORS.get(self.pack_key, 0xFF9800)
            pack_emoji = info.get("emoji", "📦")
            pack_name  = info["name"]
            num_cards  = min(info["cards"], 6)

            TIER_ROULETTE = [
                "⚪","⚪","🟢","🟢","🔵","🔵","🟣","🟣",
                "🟡","🟠","❤️","🌟","💠","✨","💎","👑",
            ]

            def _progress_bar(step: int, total: int, width: int = 14) -> str:
                filled = round((step / total) * width)
                return "█" * filled + "░" * (width - filled)

            def _slot_row(n: int) -> str:
                return "  ".join(random.choice(TIER_ROULETTE) for _ in range(n))

            # ── 0. Sealed Pack intro ──────────────────────────
            seal_e = discord.Embed(
                title  = f"{pack_emoji}  {pack_name}",
                description = (
                    f"```\n"
                    f"┌────────────────────┐\n"
                    f"│  ✦  SEALED PACK  ✦  │\n"
                    f"│   {pack_emoji}  ×{amount:<14}│\n"
                    f"│   {info.get('cards', '?')} cards inside     │\n"
                    f"└────────────────────┘\n"
                    f"```"
                    f"*Breaking the seal…*"
                ),
                color = pack_color,
            )
            await interaction.edit_original_response(embed=seal_e)
            await asyncio.sleep(0.6)

            # ── 1. Countdown ──────────────────────────────────
            COUNTDOWN = [
                ("3️⃣", ""),
                ("2️⃣", ""),
                ("1️⃣", ""),
                ("🔓", "**CRACKING OPEN!**"),
            ]
            for (icon, subtitle) in COUNTDOWN:
                desc = f"# {icon}\n{subtitle}" if subtitle else f"# {icon}"
                cnt_e = discord.Embed(
                    title       = f"{pack_emoji}  Opening {amount:,}× {pack_name}",
                    description = desc,
                    color       = pack_color,
                )
                await interaction.edit_original_response(embed=cnt_e)
                await asyncio.sleep(0.65)

            # ── 2. Slot Machine — fast spin (3 frames, ≥0.5 s each to avoid 429s) ──
            for frame_n, delay in enumerate([0.5, 0.5, 0.5]):
                spin_e = discord.Embed(
                    title       = "🎰  Spinning…",
                    description = (
                        f"```\n[ {_slot_row(num_cards)} ]\n```\n"
                        f"`{_progress_bar(frame_n+1, 14)}`  ⚡ *Spinning fast…*"
                    ),
                    color = pack_color,
                )
                await interaction.edit_original_response(embed=spin_e)
                await asyncio.sleep(delay)

            # ── 3. Slot Machine — slowing ─────────────────────
            SLOW_STAGES = [
                (0.50, "🔥  Slowing down…"),
                (0.55, "🔥  Slowing down…"),
                (0.60, "✨  Almost there…"),
                (0.65, "✨  Almost there…"),
                (0.70, "💥  DROPPING!"),
            ]
            for s_idx, (delay, label) in enumerate(SLOW_STAGES):
                slow_e = discord.Embed(
                    title       = "🎰  Spinning…",
                    description = (
                        f"```\n[ {_slot_row(num_cards)} ]\n```\n"
                        f"`{_progress_bar(6+s_idx+1, 14)}`  *{label}*"
                    ),
                    color = pack_color,
                )
                await interaction.edit_original_response(embed=slow_e)
                await asyncio.sleep(delay)

            # ── 4. Rare-Pull Flash (if applicable) ────────────
            RARE_TIERS = {"Godly","Supreme","Shiny Supreme","Secret","Boss","Shiny Boss"}
            top_pulls  = [c for c in all_cards if c.get("tier") in RARE_TIERS]
            if top_pulls:
                alert_lines = "\n".join(
                    f"{CARD_TIERS.get(c['tier'], CARD_TIERS['Common'])['emoji']}  "
                    f"**{c['species'].capitalize()}**  —  {c['tier']}"
                    + (" ✨ **SHINY!**" if c.get("shiny_variant") else "")
                    for c in top_pulls[:4]
                )
                for flash_color in [0xFF0000, 0xFFFF00]:
                    flash_e = discord.Embed(
                        title       = "🚨  ─────  RARE PULL  ─────  🚨",
                        description = alert_lines,
                        color       = flash_color,
                    )
                    flash_e.set_footer(text="Something special dropped!")
                    await interaction.edit_original_response(embed=flash_e)
                    await asyncio.sleep(0.55)

            # ── 5. Card-by-Card Reveal (single pack) ──────────
            if amount == 1:
                RARE_DELAY   = {"Godly","Supreme","Shiny Supreme","Secret","Boss","Shiny Boss"}
                MEDIUM_DELAY = {"Legendary","Epic"}
                revealed: list[str] = []
                show_cards = all_cards[:10]

                for idx, card in enumerate(show_cards):
                    ti       = CARD_TIERS.get(card["tier"], CARD_TIERS["Common"])
                    shn      = " ✨ **SHINY!**" if card.get("shiny_variant") else ""
                    sold_tag = " ♻️" if card.get("auto_sold") else ""
                    t_emoji  = TYPE_EMOJI.get(card.get("type","normal"), "⭐")
                    revealed.append(
                        f"{ti['emoji']}  **{card['species'].capitalize()}**"
                        f"  `{card['tier']}`{shn}{sold_tag}  {t_emoji}"
                    )
                    pct_done  = (idx + 1) / len(show_cards)
                    prog_bar  = "█" * round(pct_done * 12) + "░" * (12 - round(pct_done * 12))
                    rev_e = discord.Embed(
                        title       = f"🎴  Revealing  ·  Card {idx+1} of {len(show_cards)}",
                        description = "\n".join(revealed),
                        color       = pack_color,
                    )
                    rev_e.set_footer(text=f"[ {prog_bar} ]  {idx+1}/{len(show_cards)}")
                    await interaction.edit_original_response(embed=rev_e)
                    delay = (
                        0.85 if card["tier"] in RARE_DELAY
                        else 0.55 if card["tier"] in MEDIUM_DELAY
                        else 0.40
                    )
                    await asyncio.sleep(delay)

            elif amount > 1:
                # Multi-pack: quick landing frame
                sample    = random.sample(all_cards, min(num_cards, len(all_cards)))
                slot_emoj = "  ".join(
                    CARD_TIERS.get(c["tier"], CARD_TIERS["Common"])["emoji"] for c in sample
                )
                land_e = discord.Embed(
                    title       = f"💥  {amount:,}× {pack_name}  OPENED!",
                    description = (
                        f"```\n[ {slot_emoj} ]\n```\n"
                        f"**{len(all_cards):,} cards** revealed — tallying results…"
                    ),
                    color = pack_color,
                )
                await interaction.edit_original_response(embed=land_e)
                await asyncio.sleep(0.75)

            # ── 6. Final result ───────────────────────────────
            result_embed = _build_pack_open_result(self.owner, self.pack_key, all_cards, total_auto_coins, amount)
            await interaction.edit_original_response(embed=result_embed, view=InventoryPacksView(self.owner))
        finally:
            _OPENING_PACKS.discard(uid)


