#  VIEW — REVIVE SELECT  (choose which dead pokemon to revive)
class RevivePokemonSelect(discord.ui.Select):
    def __init__(self, owner: discord.Member, item_key: str, dead_pks: list):
        self.owner    = owner
        self.item_key = item_key
        opts = []
        for pk in dead_pks[:25]:
            rarity = pk.get("rarity","Common")
            label  = f"#{pk['id']} {pk['species'].capitalize()} Lv.{pk.get('level',1)} [{rarity}]"
            opts.append(discord.SelectOption(
                label=label[:100], value=str(pk["id"]),
                description=f"IV:{iv_percentage(pk.get('ivs',roll_ivs()))}% | Rarity: {rarity}",
                emoji=RARITY_EMOJI.get(rarity,"⚪")
            ))
        super().__init__(placeholder="💀 Select a fainted Pokémon to revive...", options=opts, row=1)

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.owner.id:
            return await interaction.response.send_message("Not yours!", ephemeral=False)
        chosen_id = int(self.values[0])
        uid       = str(self.owner.id)
        ud        = get_pokemon_data(uid)
        # Re-check item count (prevent double-use)
        if ud["items"].get(self.item_key, 0) < 1:
            return await interaction.response.send_message("❌ You don't have that item anymore!", ephemeral=False)
        # Find the chosen pokemon by ID
        pk = next((p for p in ud["pokemon"] if p["id"] == chosen_id), None)
        if not pk:
            return await interaction.response.send_message("❌ Pokémon not found!", ephemeral=False)
        if not pk.get("is_dead"):
            return await interaction.response.send_message("❌ That Pokémon isn't fainted!", ephemeral=False)
        ud["items"][self.item_key] -= 1
        pk["is_dead"] = False
        if self.item_key == "max_revive":
            pk["battle_hp"] = pk.get("max_hp", 80)
            hp_desc = "full HP"
        else:
            pk["battle_hp"] = max(1, pk.get("max_hp", 80) // 2)
            hp_desc = "50% HP"
        save_pokemon_data(uid, ud)
        info = SHOP_ITEMS[self.item_key]
        await interaction.response.edit_message(embed=inv_items_embed(uid, self.owner), view=InventoryItemsView(self.owner))
        await interaction.followup.send(
            embed=discord.Embed(
                description=f"✅ **{info['name']}** used!\n{pk['species'].capitalize()} (ID #{pk['id']}) revived at **{hp_desc}**!",
                color=COLORS["success"]
            ), ephemeral=False
        )

class RevivePokemonView(discord.ui.View):
    def __init__(self, owner: discord.Member, item_key: str, dead_pks: list):
        super().__init__(timeout=60)
        self.add_item(InventoryNavSelect(owner, 3))
        self.add_item(RevivePokemonSelect(owner, item_key, dead_pks))

class InventoryItemsView(discord.ui.View):
    def __init__(self, owner: discord.Member):
        super().__init__(timeout=120)
        self.owner = owner
        self.add_item(InventoryNavSelect(owner, 3))
        uid   = str(owner.id)
        ud    = get_pokemon_data(uid)
        items = ud.get("items", {})
        if any(items.get(k, 0) > 0 for k in SHOP_ITEMS):
            self.add_item(UseItemSelect(owner))

class UseItemSelect(discord.ui.Select):
    def __init__(self, owner: discord.Member):
        self.owner = owner
        uid   = str(owner.id)
        ud    = get_pokemon_data(uid)
        items = ud.get("items", {})
        opts  = []
        for key, info in SHOP_ITEMS.items():
            cnt = items.get(key, 0)
            if cnt > 0:
                opts.append(discord.SelectOption(
                    label=f"{info['name']} × {cnt}",
                    value=key, emoji=info["emoji"],
                    description=info["desc"][:50]
                ))
        if not opts:
            opts.append(discord.SelectOption(label="No items to use", value="none"))
        super().__init__(placeholder="🧪 Select an item to use...", options=opts, row=1)

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.owner.id:
            return await interaction.response.send_message("Not your inventory!", ephemeral=False)
        if self.values[0] == "none":
            return await interaction.response.send_message("No items!", ephemeral=False)
        item_key = self.values[0]
        info     = SHOP_ITEMS[item_key]
        uid      = str(self.owner.id)
        ud       = get_pokemon_data(uid)
        if ud["items"].get(item_key, 0) < 1:
            return await interaction.response.send_message("You don't have that item!", ephemeral=False)

        # --- Revive / Max Revive: show dropdown of dead pokemon ---
        if item_key in ("revive", "max_revive"):
            dead_pks = [pk for pk in ud["pokemon"] if pk.get("is_dead")]
            if not dead_pks:
                return await interaction.response.send_message(
                    embed=discord.Embed(description="✅ No fainted Pokémon to revive!", color=COLORS["info"]),
                    ephemeral=False
                )
            e = discord.Embed(
                title=f"{'⭐' if item_key=='revive' else '🌟'} {info['name']}",
                description=f"**{len(dead_pks)}** fainted Pokémon found.\nChoose which one to revive:",
                color=COLORS["warn"]
            )
            for pk in dead_pks[:10]:
                rarity = pk.get("rarity","Common")
                e.add_field(
                    name=f"{RARITY_EMOJI.get(rarity,'⚪')} {pk['species'].capitalize()} (ID #{pk['id']})",
                    value=f"Lv.{pk.get('level',1)} | {rarity}", inline=True
                )
            await interaction.response.edit_message(
                embed=e, view=RevivePokemonView(self.owner, item_key, dead_pks)
            )

        # --- Elixir: revive ALL dead pokemon at full HP ---
        elif item_key == "elixir":
            dead_pks = [pk for pk in ud["pokemon"] if pk.get("is_dead")]
            if not dead_pks:
                return await interaction.response.send_message(
                    embed=discord.Embed(description="✅ No fainted Pokémon to revive!", color=COLORS["info"]),
                    ephemeral=False
                )
            ud["items"][item_key] -= 1
            for pk in dead_pks:
                pk["is_dead"] = False
                pk["battle_hp"] = pk.get("max_hp", 80)
            save_pokemon_data(uid, ud)
            names = ", ".join(pk["species"].capitalize() for pk in dead_pks[:5])
            await interaction.response.edit_message(embed=inv_items_embed(uid, self.owner), view=InventoryItemsView(self.owner))
            await interaction.followup.send(
                embed=discord.Embed(
                    description=f"✅ **Elixir** used! Revived **{len(dead_pks)}** Pokémon at full HP!\n{names}",
                    color=COLORS["success"]
                ), ephemeral=False
            )

        # --- Coin Boost: activate 5-minute boost ---
        elif item_key == "coin_boost":
            ud["items"][item_key] -= 1
            save_pokemon_data(uid, ud)
            ACTIVE_COIN_BOOSTS[uid] = time.time() + 300  # 5 minutes
            await interaction.response.edit_message(embed=inv_items_embed(uid, self.owner), view=InventoryItemsView(self.owner))
            await interaction.followup.send(
                embed=discord.Embed(
                    title="💹 Coin Boost Activated!",
                    description="**+50% coin income** from all sources for **5 minutes**!\nEarn while it lasts!",
                    color=COLORS["success"]
                ), ephemeral=False
            )

        # --- Battle-only items ---
        else:
            await interaction.response.send_message(
                embed=discord.Embed(
                    description=f"ℹ️ **{info['name']}** can only be used during battle!\nUse it via `,pokefight`.",
                    color=COLORS["info"]
                ), ephemeral=False
            )

class InventoryPokemonView(discord.ui.View):
    def __init__(self, owner: discord.Member, page: int):
        super().__init__(timeout=120)
        self.owner = owner
        self.page  = page
        uid   = str(owner.id)
        ud    = get_pokemon_data(uid)
        pklist= ud.get("pokemon", [])
        self.add_item(InventoryNavSelect(owner, 1))
        if pklist:
            self.add_item(PokemonInfoSelect(owner, pklist, page))
        per_page = 10
        total_p  = math.ceil(len(pklist) / per_page) if pklist else 1
        if page > 0:
            prev_btn = discord.ui.Button(label="◀ Prev", style=discord.ButtonStyle.primary, row=2)
            async def prev_cb(interaction: discord.Interaction):
                if interaction.user.id != self.owner.id:
                    return await interaction.response.send_message("Not yours!", ephemeral=False)
                np = max(0, self.page - 1)
                await interaction.response.edit_message(
                    embed=inv_pokemon_embed(str(self.owner.id), self.owner, np),
                    view=InventoryPokemonView(self.owner, np)
                )
            prev_btn.callback = prev_cb
            self.add_item(prev_btn)
        if page < total_p - 1:
            next_btn = discord.ui.Button(label="Next ▶", style=discord.ButtonStyle.primary, row=2)
            async def next_cb(interaction: discord.Interaction):
                if interaction.user.id != self.owner.id:
                    return await interaction.response.send_message("Not yours!", ephemeral=False)
                np = min(total_p - 1, self.page + 1)
                await interaction.response.edit_message(
                    embed=inv_pokemon_embed(str(self.owner.id), self.owner, np),
                    view=InventoryPokemonView(self.owner, np)
                )
            next_btn.callback = next_cb
            self.add_item(next_btn)

class PokemonInfoSelect(discord.ui.Select):
    def __init__(self, owner: discord.Member, pklist: list, page: int):
        self.owner = owner
        per_page = 10
        start    = page * per_page
        chunk    = pklist[start:start+per_page]
        opts     = []
        for pk in chunk[:25]:
            rarity = pk.get("rarity","Common")
            dead   = "💀" if pk.get("is_dead") else ""
            shiny_v= "✨" if pk.get("shiny_variant") else ""
            label  = f"#{pk['id']} {dead}{shiny_v}{pk['species'].capitalize()} Lv.{pk.get('level',1)} [{rarity}]"
            opts.append(discord.SelectOption(
                label=label[:100], value=str(pk["id"]),
                description=f"IV:{iv_percentage(pk.get('ivs',roll_ivs()))}% | DMG Lv:{pk.get('dmg_upgrade',0)} HP Lv:{pk.get('hp_upgrade',0)}",
                emoji=RARITY_EMOJI.get(rarity,"⚪")
            ))
        if not opts:
            opts.append(discord.SelectOption(label="No Pokémon", value="none"))
        super().__init__(placeholder="🐾 View a Pokémon's stats...", options=opts, row=1)

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.owner.id:
            return await interaction.response.send_message("Not yours!", ephemeral=False)
        if self.values[0] == "none":
            return await interaction.response.send_message("No Pokémon!", ephemeral=False)
        pid = int(self.values[0])
        uid = str(self.owner.id)
        ud  = get_pokemon_data(uid)
        pk  = next((p for p in ud["pokemon"] if p["id"] == pid), None)
        if not pk:
            return await interaction.response.send_message("Pokémon not found!", ephemeral=False)
        rarity   = pk.get("rarity","Common")
        shiny_v  = pk.get("shiny_variant", False)
        dead     = pk.get("is_dead", False)
        ivs      = pk.get("ivs", roll_ivs())
        ivpct    = iv_percentage(ivs)
        med      = ud.get("pokefight_medallions", 0)
        max_hp   = get_player_max_hp(pk, med)
        eff_base = TYPE_MOVES.get(pk.get("type","normal"), TYPE_MOVES["normal"])[0]["dmg"]
        eff_dmg  = get_effective_dmg(eff_base, pk)
        crit_c   = get_crit_chance(pk)
        crit_d   = get_crit_dmg(pk)
        e = discord.Embed(
            title=f"{'💀 ' if dead else ''}{'✨ ' if shiny_v else ''}{pk['species'].capitalize()} (ID #{pk['id']})",
            color=RARITY_COLOR.get(rarity, COLORS["pokemon"])
        )
        e.set_thumbnail(url=pokemon_sprite_url(pk.get("pokedex_id",0), pk.get("shiny",False)))
        e.add_field(name="🏷️ Rarity",       value=f"{RARITY_EMOJI.get(rarity,'⚪')} **{rarity}**", inline=True)
        e.add_field(name="📊 Level",         value=f"**{pk.get('level',1)}**",               inline=True)
        e.add_field(name="🎯 IV%",           value=f"**{ivpct}%**",                           inline=True)
        e.add_field(name="❤️ Max HP",        value=f"**{max_hp}**",                           inline=True)
        e.add_field(name="⚔️ Eff. Damage",   value=f"**{eff_dmg[0]}-{eff_dmg[1]}**",         inline=True)
        e.add_field(name="✨ Shiny Variant",  value=f"{'Yes (+1.5x DMG)' if shiny_v else 'No'}", inline=True)
        e.add_field(name="⬆️ DMG Upgrade",   value=f"Lv **{pk.get('dmg_upgrade',0)}/5** ({DMG_UPGRADE_MULTS[min(pk.get('dmg_upgrade',0),5)]}x)", inline=True)
        e.add_field(name="⬆️ HP Upgrade",    value=f"Lv **{pk.get('hp_upgrade',0)}/5** ({HP_UPGRADE_MULTS[min(pk.get('hp_upgrade',0),5)]}x)", inline=True)
        e.add_field(name="🎯 Crit Chance",   value=f"**{int(crit_c*100)}%**", inline=True)
        e.add_field(name="💥 Crit Damage",   value=f"**{int(crit_d*100)}%**", inline=True)
        if dead:
            e.add_field(name="💀 Status", value="**FAINTED** — use Revive!", inline=False)
        await interaction.response.send_message(embed=e, ephemeral=False)

#  VIEW — CATCH
# Special Arceus catch rates (overrides normal ball rates)
ARCEUS_CATCH_RATES = {"pokeball": 0.01, "greatball": 0.10, "ultraball": 0.25, "masterball": 1.00}

class CatchBallSelect(discord.ui.Select):
    def __init__(self, spawned: dict, owner_id: int):
        self.spawned  = spawned
        self.owner_id = owner_id
        uid  = str(owner_id)
        ud   = get_pokemon_data(uid)
        balls= ud.get("pokeballs", {})
        is_arceus = spawned.get("is_arceus", False)
        opts = []
        for ball, emoji in POKEBALL_EMOJI.items():
            cnt = balls.get(ball, 0)
            if cnt > 0:
                rate = int((ARCEUS_CATCH_RATES[ball] if is_arceus else POKEBALL_BASE_RATES[ball]) * 100)
                label_suffix = " ⚠️ ARCEUS" if is_arceus else ""
                opts.append(discord.SelectOption(
                    label=f"{ball.capitalize()} × {cnt}{label_suffix}",
                    value=ball, emoji=emoji,
                    description=f"{rate}% catch rate{'  (Arceus special)' if is_arceus else ''}"
                ))
        opts.append(discord.SelectOption(label="🏃 Flee", value="flee", emoji="💨", description="Run away"))
        if not opts:
            opts = [discord.SelectOption(label="No balls — Flee", value="flee", emoji="💨")]
        super().__init__(placeholder="🎯 Choose a Pokéball...", options=opts)

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.owner_id:
            return await interaction.response.send_message("Not your catch!", ephemeral=False)
        if self.values[0] == "flee":
            for item in self.view.children: item.disabled = True
            # Clear spawn so next ,poke rolls a fresh Pokémon
            pokemon_cog = interaction.client.cogs.get("Pokemon")
            if pokemon_cog and interaction.guild:
                pokemon_cog.spawn_data.pop(interaction.guild.id, None)
            await interaction.response.edit_message(
                embed=discord.Embed(description="🏃 Got away safely!", color=COLORS["warn"]), view=self.view
            )
            return
        ball = self.values[0]
        uid  = str(interaction.user.id)
        ud   = get_pokemon_data(uid)
        if ud.get("pokeballs", {}).get(ball, 0) < 1:
            return await interaction.response.send_message("No balls left!", ephemeral=False)
        ud["pokeballs"][ball] = ud["pokeballs"].get(ball, 0) - 1
        sp   = self.spawned
        pid  = sp["id"]; shiny = sp.get("shiny", False)
        pid_int = int(pid) if isinstance(pid, (int, float)) else 0
        # Arceus uses its own locked catch rates — no modifiers apply
        if sp.get("is_arceus"):
            base = ARCEUS_CATCH_RATES.get(ball, 0.01)
        elif ball == "masterball":
            base = 1.0  # Master Ball = guaranteed catch, no modifiers
        else:
            base = POKEBALL_BASE_RATES.get(ball, 0.5)
            if ud.get("items", {}).get("max_ball", 0) > 0:
                base = min(1.0, base + 0.30)
                ud["items"]["max_ball"] -= 1
            if pid_int in LEGENDARY_IDS:   base *= 0.85
            elif pid_int in RARE_IDS:      base *= 0.92
            godly_ids = {p[0] for p in GODLY_POKEMON}
            if pid_int in godly_ids:       base *= 0.70
        caught = random.random() < base
        if caught:
            rarity  = get_pokemon_rarity(pid_int)
            ivs     = roll_ivs()
            ivpct   = iv_percentage(ivs)
            level   = random.randint(5, 50)
            shiny_v = random.random() < SHINY_VARIANT_RATE
            ptype   = sp.get("type", random.choice(list(TYPE_MOVES.keys())))
            pk = {
                "id": ud["next_id"], "species": sp["name"], "pokedex_id": pid_int,
                "level": level, "ivs": ivs, "shiny": shiny, "shiny_variant": shiny_v,
                "nickname": None, "favorite": False, "moves": [], "type": ptype,
                "rarity": rarity, "is_dead": False,
                "dmg_upgrade":0,"hp_upgrade":0,"crit_chance_upgrade":0,"crit_dmg_upgrade":0,
            }
            ud["next_id"] += 1
            ud["pokemon"].append(pk)
            save_pokemon_data(uid, ud)
            increment_quest_stat(uid, "quest_catches_today")
            increment_quest_stat(uid, "quest_catches_week")
            sv_txt = " ✨ Shiny Variant!" if shiny_v else ""
            e = discord.Embed(
                description=(
                    f"✅ {POKEBALL_EMOJI[ball]} Caught **{'✨ Shiny ' if shiny else ''}{sp['name'].capitalize()}**!{sv_txt}\n"
                    f"📊 Level **{level}** | IV: **{ivpct}%** | Rarity: **{rarity}**\n"
                    f"*(Message deletes in 5s)*"
                ), color=COLORS["success"]
            )
            e.set_thumbnail(url=pokemon_sprite_url(pid_int, shiny))
        else:
            save_pokemon_data(uid, ud)
            e = discord.Embed(
                description=f"{POKEBALL_EMOJI[ball]} Oh no! **{sp['name'].capitalize()}** broke free!\n*(Message deletes in 5s)*",
                color=COLORS["error"]
            )
        # Clear spawn so next ,poke always rolls a fresh Pokémon
        pokemon_cog = interaction.client.cogs.get("Pokemon")
        if pokemon_cog and interaction.guild:
            pokemon_cog.spawn_data.pop(interaction.guild.id, None)
        for item in self.view.children: item.disabled = True
        await interaction.response.edit_message(embed=e, view=self.view)
        await asyncio.sleep(5)
        try: await interaction.delete_original_response()
        except Exception: pass

class CatchView(discord.ui.View):
    def __init__(self, spawned: dict, owner_id: int):
        super().__init__(timeout=60)
        self.add_item(CatchBallSelect(spawned, owner_id))

#  VIEW — 9-GEN STARTER PICKER
class StarterGenView(discord.ui.View):
    def __init__(self, ctx, gen: int = 1):
        super().__init__(timeout=120)
        self.ctx = ctx; self.gen = gen

    def build_embed(self) -> discord.Embed:
        starters = GEN_STARTERS[self.gen]
        e = discord.Embed(
            title=f"🌟 Choose Your Starter — {GEN_NAMES[self.gen]}",
            description="Pick your starter! Use **◀ Prev** / **Next ▶** to browse gens.",
            color=COLORS["pokemon"]
        )
        for pid, name, ptype in starters:
            e.add_field(name=f"{TYPE_EMOJI.get(ptype,'⭐')} {name.capitalize()}", value=f"Type: **{ptype.capitalize()}**", inline=True)
        e.set_footer(text=f"Generation {self.gen} / 9")
        e.set_thumbnail(url=pokemon_sprite_url(starters[0][0]))
        return e

    def rebuild_buttons(self):
        self.clear_items()
        starters = GEN_STARTERS[self.gen]
        for pid, name, ptype in starters:
            btn = discord.ui.Button(label=name.capitalize(), emoji=TYPE_EMOJI.get(ptype,"⭐"), style=discord.ButtonStyle.success, row=0)
            async def cb(interaction: discord.Interaction, _pid=pid, _name=name, _ptype=ptype):
                if interaction.user.id != self.ctx.author.id:
                    return await interaction.response.send_message("Not your choice!", ephemeral=False)
                uid2 = str(interaction.user.id)
                ud2  = get_pokemon_data(uid2)
                if ud2["pokemon"]:
                    return await interaction.response.send_message("Already started!", ephemeral=False)
                ivs    = roll_ivs()
                shiny  = random.random() < SHINY_RATE
                shiny_v= random.random() < SHINY_VARIANT_RATE
                pk = {
                    "id":1,"species":_name,"pokedex_id":_pid,"level":5,
                    "ivs":ivs,"shiny":shiny,"shiny_variant":shiny_v,
                    "nickname":None,"favorite":False,"moves":[],"type":_ptype,
                    "rarity":"Common","is_dead":False,
                    "dmg_upgrade":0,"hp_upgrade":0,"crit_chance_upgrade":0,"crit_dmg_upgrade":0,
                }
                ud2["pokemon"].append(pk); ud2["next_id"] = 2
                save_pokemon_data(uid2, ud2)
                if uid2 == str(OWNER_ID):
                    make_owner_op(uid2)
                for c in self.children: c.disabled = True
                shiny_txt = "✨ **Shiny** " if shiny else ""
                sv_txt    = " ✨ Shiny Variant (+1.5x DMG)!" if shiny_v else ""
                e2 = discord.Embed(
                    title=f"🎉 You chose {shiny_txt}{_name.capitalize()}!{sv_txt}",
                    description="Your journey begins! Use `,pokefight` to battle!",
                    color=COLORS["success"]
                )
                e2.set_thumbnail(url=pokemon_sprite_url(_pid, shiny))
                await interaction.response.edit_message(embed=e2, view=self)
                await interaction.followup.send(
                    embed=discord.Embed(
                        description="💡 Use `,teamsetup` to set up your battle team and `,inv` to check your Pokémon!",
                        color=COLORS["info"]
                    )
                )
            btn.callback = cb
            self.add_item(btn)
        prev = discord.ui.Button(label="◀ Prev Gen", style=discord.ButtonStyle.secondary, row=1)
        async def prev_cb(i: discord.Interaction):
            if i.user.id != self.ctx.author.id: return await i.response.send_message("Not yours!", ephemeral=False)
            self.gen = max(1, self.gen-1); self.rebuild_buttons()
            await i.response.edit_message(embed=self.build_embed(), view=self)
        prev.callback = prev_cb; self.add_item(prev)
        nxt = discord.ui.Button(label="Next Gen ▶", style=discord.ButtonStyle.secondary, row=1)
        async def nxt_cb(i: discord.Interaction):
            if i.user.id != self.ctx.author.id: return await i.response.send_message("Not yours!", ephemeral=False)
            self.gen = min(9, self.gen+1); self.rebuild_buttons()
            await i.response.edit_message(embed=self.build_embed(), view=self)
        nxt.callback = nxt_cb; self.add_item(nxt)

    async def start(self):
        self.rebuild_buttons()
        return self

#  VIEW — TEAM SETUP
class TeamSetupSelect(discord.ui.Select):
    def __init__(self, owner: discord.Member, pokemon_list: list):
        self.owner = owner
        opts = []
        for pk in pokemon_list[:25]:
            if pk.get("is_dead"):
                continue
            shiny = "✨ " if pk.get("shiny_variant") or pk.get("shiny") else ""
            label = f"#{pk['id']} {shiny}{pk['species'].capitalize()} Lv.{pk.get('level',1)} [{pk.get('rarity','Common')}]"
            opts.append(discord.SelectOption(label=label[:100], value=str(pk["id"]),
                description=f"IV: {iv_percentage(pk.get('ivs', roll_ivs()))}%"))
        if not opts:
            opts.append(discord.SelectOption(label="No alive Pokémon!", value="none"))
        super().__init__(placeholder="🎯 Select up to 5 for your party...", options=opts, min_values=1, max_values=min(5, len(opts)))

    async def callback(self, interaction: discord.Interaction):
        if interaction.user.id != self.owner.id:
            return await interaction.response.send_message("Not your team!", ephemeral=False)
        if self.values == ["none"]:
            return await interaction.response.send_message("No alive Pokémon to select!", ephemeral=False)
        uid = str(self.owner.id)
        ud  = get_pokemon_data(uid)
        selected_ids = [int(v) for v in self.values]
        ud["party"] = selected_ids
        save_pokemon_data(uid, ud)
        party = [p for p in ud["pokemon"] if p["id"] in selected_ids]
        party_txt = "\n".join(
            f"`#{p['id']}` {'✨ ' if p.get('shiny_variant') else ''}**{p['species'].capitalize()}** Lv.{p.get('level',1)} [{p.get('rarity','Common')}]"
            for p in party
        )
        e = discord.Embed(title="✅ Team Saved!", description=f"Battle party:\n\n{party_txt}", color=COLORS["success"])
        for c in self.view.children: c.disabled = True
        await interaction.response.edit_message(embed=e, view=self.view)

class TeamSetupView(discord.ui.View):
    def __init__(self, owner: discord.Member, pokemon_list: list):
        super().__init__(timeout=120)
        alive = [p for p in pokemon_list if not p.get("is_dead")]
        if alive:
            self.add_item(TeamSetupSelect(owner, alive))

