CMDS_PER_PAGE: int = 15   # commands shown per help category page

def _fmt_commands(cmds: list) -> str:
    """Format a list of (cmd, desc) tuples into a clean aligned block."""
    lines = []
    for cmd, desc in cmds:
        if not desc:
            # Section header row — bold, full width
            lines.append(f"\n**{cmd}**")
        else:
            lines.append(f"`{cmd}` — {desc}")
    return "\n".join(lines).strip()

def _can_see_premium(author_id: int, guild: discord.Guild | None) -> bool:
    """Returns True if this user may see premium-only help categories. Everyone can see Admin."""
    return True

def _visible_categories(author_id: int, guild: discord.Guild | None) -> dict:
    """Return only the HELP_CATEGORIES this user is allowed to see."""
    premium = _can_see_premium(author_id, guild)
    return {
        k: v for k, v in HELP_CATEGORIES.items()
        if not v.get("premium_only", False) or premium
    }

def build_help_category(key: str, page: int = 0) -> discord.Embed:
    cat = HELP_CATEGORIES[key]
    cmds = cat["cmds"]
    total_pages = max(1, math.ceil(len(cmds) / CMDS_PER_PAGE))
    page = max(0, min(page, total_pages - 1))
    start = page * CMDS_PER_PAGE
    page_cmds = cmds[start:start + CMDS_PER_PAGE]
    page_suffix = f"  •  Page {page + 1}/{total_pages}" if total_pages > 1 else ""
    e = discord.Embed(
        title=f"{cat['emoji']}  {cat['label']} Commands{page_suffix}",
        description=f"*{cat['desc']}*\n\n{_fmt_commands(page_cmds)}",
        color=cat["color"],
    )
    e.set_footer(text=f"Coolbot  •  Prefix: {PREFIX}  •  {len(cmds)} commands total  •  🏠 Home to return")
    return e

def build_help_home(author_id: int = 0, guild: discord.Guild | None = None) -> discord.Embed:
    # Show the CURRENT server's stats — the server where ,help was run
    # Falls back to the bot's home server if used in DMs
    g = guild or bot.get_guild(REQUIRED_GUILD_ID)

    if g:
        guild_name   = g.name
        guild_id_str = str(g.id)
        icon_url     = str(g.icon.url) if g.icon else None
        member_count = f"{g.member_count:,}"
        boost_level  = g.premium_tier
        boost_count  = g.premium_subscription_count
        roles_count  = len(g.roles)
        emojis_count = len(g.emojis)
        channels_count = len(g.channels)
        created_at   = f"<t:{int(g.created_at.timestamp())}:D>"
        # Online count — only accurate when members intent is on
        online = "?"
        if g.members:
            _on = sum(1 for m in g.members if m.status != discord.Status.offline and not m.bot)
            online = f"{_on:,}"
    else:
        guild_name     = "Coolbot"
        guild_id_str   = "—"
        icon_url       = None
        member_count   = "?"
        boost_level    = 0
        boost_count    = 0
        roles_count    = 0
        emojis_count   = 0
        channels_count = 0
        created_at     = "?"
        online         = "?"

    # Bot invite link — use custom ServerLink if set, otherwise the default
    invite_url = _DEFAULT_SERVER_LINK or REQUIRED_GUILD_INVITE

    e = discord.Embed(
        title=f"🐻‍❄️  {guild_name}",
        description=(
            f"🔗 **[Join Coolbot's Server]({invite_url})**\n\n"
            f"👥 **Members:** {member_count}  •  🟢 **Online:** {online}\n"
            f"💎 **Boost Level {boost_level}**  •  **{boost_count}** boosts\n"
            f"💬 **Channels:** {channels_count}  •  🎭 **Roles:** {roles_count}  •  😀 **Emojis:** {emojis_count}\n"
            f"📅 **Created:** {created_at}\n\n"
            f"**Pick a category from the dropdown ↓**"
        ),
        color=0x5865F2,
    )
    if icon_url:
        e.set_thumbnail(url=icon_url)
    e.set_footer(text=f"Coolbot 🐻‍❄️  •  Prefix: {PREFIX}  •  Server ID: {guild_id_str}")
    return e



class HelpCategorySelect(discord.ui.Select):
    def __init__(self, author_id: int = 0, guild: discord.Guild | None = None, current_key: str = "__home__"):
        self.author_id = author_id
        self.guild     = guild
        visible = _visible_categories(author_id, guild)
        opts = [
            discord.SelectOption(
                label="Home",
                value="__home__",
                emoji="🏠",
                description="Show server info & invite link",
                default=(current_key == "__home__"),
            )
        ] + [
            discord.SelectOption(
                label=cat["label"],
                value=key,
                emoji=cat["emoji"],
                description=f"{cat['desc'][:50]}  •  {len(cat['cmds'])} cmds",
                default=(current_key == key),
            )
            for key, cat in visible.items()
        ]
        super().__init__(placeholder="📂  Choose a category...", options=opts, min_values=1, max_values=1, row=0)

    async def callback(self, interaction: discord.Interaction):
        key = self.values[0]
        if key == "__home__":
            await interaction.response.edit_message(
                embed=build_help_home(self.author_id, self.guild),
                view=HelpView(self.author_id, self.guild),
            )
        else:
            await interaction.response.edit_message(
                embed=build_help_category(key, 0),
                view=HelpPageView(key, 0, self.author_id, self.guild),
            )

class HelpPageView(discord.ui.View):
    """View for a single category page — has Prev/Next when there are multiple pages."""
    def __init__(self, category_key: str, page: int = 0,
                 author_id: int = 0, guild: discord.Guild | None = None):
        super().__init__(timeout=180)
        self.category_key = category_key
        self.page         = page
        self.author_id    = author_id
        self.guild        = guild
        self._rebuild()

    def _total_pages(self) -> int:
        return max(1, math.ceil(len(HELP_CATEGORIES[self.category_key]["cmds"]) / CMDS_PER_PAGE))

    def _rebuild(self):
        self.clear_items()
        self.add_item(HelpCategorySelect(self.author_id, self.guild, current_key=self.category_key))
        total = self._total_pages()
        if total > 1:
            prev_btn = discord.ui.Button(
                label="◀ Prev", style=discord.ButtonStyle.secondary,
                row=1, disabled=(self.page == 0),
            )
            async def prev_cb(interaction: discord.Interaction, _self=self):
                _self.page -= 1
                _self._rebuild()
                await interaction.response.edit_message(
                    embed=build_help_category(_self.category_key, _self.page), view=_self
                )
            prev_btn.callback = prev_cb
            self.add_item(prev_btn)

            next_btn = discord.ui.Button(
                label="Next ▶", style=discord.ButtonStyle.primary,
                row=1, disabled=(self.page >= total - 1),
            )
            async def next_cb(interaction: discord.Interaction, _self=self):
                _self.page += 1
                _self._rebuild()
                await interaction.response.edit_message(
                    embed=build_help_category(_self.category_key, _self.page), view=_self
                )
            next_btn.callback = next_cb
            self.add_item(next_btn)

class HelpView(discord.ui.View):
    """Initial home view — dropdown only, Home button removed."""
    def __init__(self, author_id: int = 0, guild: discord.Guild | None = None):
        super().__init__(timeout=180)
        self.add_item(HelpCategorySelect(author_id, guild))

#  COG — MODERATION
async def _dm_owner_mod(bot_ref, action: str, mod, target, guild, reason: str = "", extra: str = ""):
    """DM the owner with a moderation action log."""
    try:
        owner = await bot_ref.fetch_user(OWNER_ID)
        emoji_map  = {"Warn":"⚠️","Ban":"🔨","Unban":"✅","Kick":"👢","Mute":"🔇","Unmute":"🔊"}
        color_map  = {"Warn":0xFEE75C,"Ban":0xED4245,"Unban":0x57F287,"Kick":0xFF6B35,"Mute":0xFF9800,"Unmute":0x57F287}
        e = discord.Embed(
            title=f"{emoji_map.get(action,'📋')} Mod Action — {action}",
            color=color_map.get(action, COLORS["warn"])
        )
        e.add_field(name="🖥️ Server",     value=f"**{guild.name}**\nID: `{guild.id}`", inline=True)
        e.add_field(name="🛡️ Moderator", value=f"**{mod}** (`{mod.id}`)",              inline=True)
        tval = f"**{target}** (`{getattr(target,'id','?')}`)" if hasattr(target,"id") else str(target)
        e.add_field(name="🎯 Target",     value=tval,                                   inline=True)
        if reason:
            e.add_field(name="📝 Reason", value=reason, inline=False)
        if extra:
            e.add_field(name="ℹ️ Info",   value=extra,  inline=False)
        e.set_footer(text=datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC"))
        await owner.send(embed=e)
    except Exception:
        pass

class Moderation(commands.Cog):
    def __init__(self, bot): self.bot = bot

    @commands.hybrid_command(name="warn")
    async def warn(self, ctx, member: discord.Member, *, reason: str = "No reason"):
        if not is_staff(ctx.author): return
        uid = str(member.id)
        data= load("warnings"); gw = gdata(data, ctx.guild.id)
        gw.setdefault(uid, []).append({"reason":reason,"mod":str(ctx.author),"time":datetime.now(timezone.utc).isoformat()})
        save("warnings", data)
        total = len(gw[uid])
        await ctx.send(embed=discord.Embed(description=f"⚠️ **{member.display_name}** warned: {reason} ({total} total)", color=COLORS["warn"]))
        await _dm_owner_mod(ctx.bot, "Warn", ctx.author, member, ctx.guild, reason=reason, extra=f"Total warnings: {total}")

    @commands.command(name="unwarn")
    async def unwarn(self, ctx, member: discord.Member):
        if not is_staff(ctx.author): return
        if member.id == ctx.author.id:
            return await ctx.send(embed=discord.Embed(description="❌ You cannot remove your own warnings.", color=COLORS["error"]))
        uid = str(member.id); data = load("warnings"); gw = gdata(data, ctx.guild.id)
        if uid not in gw or not gw[uid]:
            return await ctx.send(embed=discord.Embed(description="No warnings found.", color=COLORS["info"]))
        gw[uid].pop(); save("warnings", data)
        await ctx.send(embed=discord.Embed(description=f"✅ Latest warning removed from **{member.display_name}**.", color=COLORS["success"]))

    @commands.command(name="warnings")
    async def warnings(self, ctx, member: discord.Member = None):
        member = member or ctx.author
        uid = str(member.id); data = load("warnings"); gw = gdata(data, ctx.guild.id)
        warns = gw.get(uid, [])
        if not warns:
            return await ctx.send(embed=discord.Embed(description=f"**{member.display_name}** has no warnings.", color=COLORS["info"]))
        e = discord.Embed(title=f"⚠️ {member.display_name}'s Warnings ({len(warns)})", color=COLORS["warn"])
        for i, w in enumerate(warns[-10:], 1):
            e.add_field(name=f"#{i} — {w.get('time','?')[:10]}", value=f"**Reason:** {w.get('reason','?')}\n**Mod:** {w.get('mod','?')}", inline=False)
        await ctx.send(embed=e)

    @commands.hybrid_command(name="kick")
    async def kick(self, ctx, member: discord.Member, *, reason: str = "No reason"):
        if not is_staff(ctx.author): return
        try:
            await member.kick(reason=reason)
            await ctx.send(embed=discord.Embed(description=f"👢 **{member.display_name}** kicked: {reason}", color=COLORS["warn"]))
            await _dm_owner_mod(ctx.bot, "Kick", ctx.author, member, ctx.guild, reason=reason)
        except discord.Forbidden:
            await ctx.send(embed=discord.Embed(description="❌ I don't have permission to kick that member.", color=COLORS["error"]))

    @commands.hybrid_command(name="ban")
    async def ban(self, ctx, member: discord.Member, *, reason: str = "No reason"):
        if not is_staff(ctx.author): return
        try:
            # DM the member BEFORE banning — once banned they can no longer receive guild DMs
            try:
                dm_e = discord.Embed(
                    title="🔨  You Have Been Banned",
                    description=f"You were banned from **{ctx.guild.name}**.",
                    color=COLORS["error"],
                )
                dm_e.add_field(name="📝 Reason",     value=reason,           inline=False)
                dm_e.add_field(name="🛡️ Banned By", value=str(ctx.author),  inline=False)
                dm_e.add_field(name="🖥️ Server ID",  value=f"`{ctx.guild.id}`", inline=False)
                dm_e.set_footer(text="Coolbot")
                await member.send(embed=dm_e)
            except Exception:
                pass  # DMs disabled or blocked — still proceed with the ban
            await member.ban(reason=reason)
            await ctx.send(embed=discord.Embed(description=f"🔨 **{member.display_name}** banned: {reason}", color=COLORS["error"]))
            await _dm_owner_mod(ctx.bot, "Ban", ctx.author, member, ctx.guild, reason=reason)
        except discord.Forbidden:
            await ctx.send(embed=discord.Embed(description="❌ No permission to ban.", color=COLORS["error"]))

    @commands.hybrid_command(name="unban", description="Unban a user from a server the bot is in")
    async def unban(self, ctx, user_id: str, guild_id: str):
        if not is_owner(ctx.author): return
        try:
            uid = int(user_id)
        except ValueError:
            return await ctx.send(embed=discord.Embed(description="❌ User ID must be a number.\n**Usage:** ```,unban (user_id) (guild_id)```", color=COLORS["error"]))
        try:
            gid = int(guild_id)
        except ValueError:
            return await ctx.send(embed=discord.Embed(description="❌ Guild ID must be a number.\n**Usage:** ```,unban (user_id) (guild_id)```", color=COLORS["error"]))
        g = bot.get_guild(gid)
        if not g:
            return await ctx.send(embed=discord.Embed(description=f"❌ Bot is not in server ``{gid}``.", color=COLORS["error"]))
        target = discord.Object(id=uid)
        try:
            await g.unban(target, reason=f"Unban by {ctx.author}")
            await ctx.send(embed=discord.Embed(
                description=f"✅ Unbanned ``{uid}`` from **{g.name}** (``{gid}``)",
                color=COLORS["success"]
            ))
        except discord.NotFound:
            await ctx.send(embed=discord.Embed(description=f"ℹ️ ``{uid}`` is not banned in **{g.name}**.", color=COLORS["info"]))
        except discord.Forbidden:
            await ctx.send(embed=discord.Embed(description=f"❌ No **Ban Members** permission in **{g.name}**.", color=COLORS["error"]))
        except Exception as ex:
            await ctx.send(embed=discord.Embed(description=f"❌ Error: ``{ex}``", color=COLORS["error"]))

    @commands.hybrid_command(name="mute")
    async def mute(self, ctx, member: discord.Member, duration: str = "5m"):
        if not is_staff(ctx.author): return
        secs = parse_duration(duration) or 300
        try:
            until = discord.utils.utcnow() + timedelta(seconds=secs)
            await member.timeout(until, reason=f"Muted by {ctx.author}")
            dur_str = format_duration(secs)
            await ctx.send(embed=discord.Embed(description=f"🔇 **{member.display_name}** muted for **{dur_str}**.", color=COLORS["warn"]))
            await _dm_owner_mod(ctx.bot, "Mute", ctx.author, member, ctx.guild, extra=f"Duration: {dur_str}")
        except Exception as ex:
            await ctx.send(embed=discord.Embed(description=f"❌ {ex}", color=COLORS["error"]))

    @commands.hybrid_command(name="unmute")
    async def unmute(self, ctx, member: discord.Member):
        if not is_staff(ctx.author): return
        try:
            await member.timeout(None)
            await ctx.send(embed=discord.Embed(description=f"🔊 **{member.display_name}** unmuted.", color=COLORS["success"]))
            await _dm_owner_mod(ctx.bot, "Unmute", ctx.author, member, ctx.guild)
        except Exception as ex:
            await ctx.send(embed=discord.Embed(description=f"❌ {ex}", color=COLORS["error"]))

    @commands.hybrid_command(name="purge")
    async def purge(self, ctx, amount: int = 10):
        if not is_staff(ctx.author): return
        amount = min(amount, 500)
        try:
            deleted = await ctx.channel.purge(limit=amount+1)
            m = await ctx.send(embed=discord.Embed(description=f"🗑️ Deleted **{len(deleted)-1}** messages.", color=COLORS["success"]))
            await asyncio.sleep(3)
            try: await m.delete()
            except: pass
        except Exception as ex:
            await ctx.send(embed=discord.Embed(description=f"❌ {ex}", color=COLORS["error"]))

    @commands.hybrid_command(name="lock")
    async def lock(self, ctx):
        if not is_staff(ctx.author): return
        overwrite = ctx.channel.overwrites_for(ctx.guild.default_role)
        overwrite.send_messages = False
        await ctx.channel.set_permissions(ctx.guild.default_role, overwrite=overwrite)
        await ctx.send(embed=discord.Embed(description="🔒 Channel locked.", color=COLORS["warn"]))

    @commands.hybrid_command(name="unlock")
    async def unlock(self, ctx):
        if not is_staff(ctx.author): return
        overwrite = ctx.channel.overwrites_for(ctx.guild.default_role)
        overwrite.send_messages = True
        await ctx.channel.set_permissions(ctx.guild.default_role, overwrite=overwrite)
        await ctx.send(embed=discord.Embed(description="🔓 Channel unlocked.", color=COLORS["success"]))

    @commands.command(name="slowmode")
    async def slowmode(self, ctx, seconds: int = 0):
        if not is_staff(ctx.author): return
        await ctx.channel.edit(slowmode_delay=max(0, min(seconds, 21600)))
        await ctx.send(embed=discord.Embed(description=f"🐢 Slowmode set to **{seconds}s**.", color=COLORS["info"]))

    @commands.command(name="setnick")
    async def setnick(self, ctx, member: discord.Member, *, name: str = ""):
        if not is_staff(ctx.author): return
        try:
            await member.edit(nick=name or None)
            await ctx.send(embed=discord.Embed(description=f"✅ Nickname {'set to **'+name+'**' if name else 'cleared'} for **{member.display_name}**.", color=COLORS["success"]))
        except Exception as ex:
            await ctx.send(embed=discord.Embed(description=f"❌ {ex}", color=COLORS["error"]))

    @commands.command(name="role")
    async def role(self, ctx, member: discord.Member, *, role: discord.Role):
        if not is_staff(ctx.author): return
        try:
            if role in member.roles:
                await member.remove_roles(role)
                await ctx.send(embed=discord.Embed(description=f"✅ Removed **{role.name}** from **{member.display_name}**.", color=COLORS["warn"]))
            else:
                await member.add_roles(role)
                await ctx.send(embed=discord.Embed(description=f"✅ Added **{role.name}** to **{member.display_name}**.", color=COLORS["success"]))
        except Exception as ex:
            await ctx.send(embed=discord.Embed(description=f"❌ {ex}", color=COLORS["error"]))

    @commands.command(name="massrole")
    async def massrole(self, ctx, *, role: discord.Role):
        if not is_owner(ctx.author): return
        count = 0
        for m in ctx.guild.members:
            try: await m.add_roles(role); count += 1
            except: pass
        await ctx.send(embed=discord.Embed(description=f"✅ Gave **{role.name}** to **{count}** members.", color=COLORS["success"]))

    @commands.command(name="massban")
    async def massban(self, ctx, *, ids: str):
        if not is_owner(ctx.author): return
        count = 0
        for uid_str in ids.split():
            try:
                user = await bot.fetch_user(int(uid_str.strip()))
                await ctx.guild.ban(user, reason="Mass ban")
                count += 1
            except: pass
        await ctx.send(embed=discord.Embed(description=f"🔨 Banned **{count}** users.", color=COLORS["success"]))

    @commands.command(name="snipe")
    async def snipe(self, ctx):
        data = bot.snipe_data.get(ctx.channel.id)
        if not data:
            return await ctx.send(embed=discord.Embed(description="Nothing to snipe!", color=COLORS["info"]))
        e = discord.Embed(description=data["content"], color=COLORS["main"])
        e.set_author(name=data["author"], icon_url=data["avatar"])
        e.set_footer(text="Deleted message")
        await ctx.send(embed=e)

    @commands.command(name="editsnipe")
    async def editsnipe(self, ctx):
        data = bot.editsnipe_data.get(ctx.channel.id)
        if not data:
            return await ctx.send(embed=discord.Embed(description="Nothing to edit-snipe!", color=COLORS["info"]))
        e = discord.Embed(color=COLORS["main"])
        e.set_author(name=data["author"], icon_url=data["avatar"])
        e.add_field(name="Before", value=data["before"], inline=False)
        e.add_field(name="After",  value=data["after"],  inline=False)
        await ctx.send(embed=e)

    @commands.command(name="avatar")
    async def avatar(self, ctx, member: discord.Member = None):
        member = member or ctx.author
        e = discord.Embed(title=f"{member.display_name}'s Avatar", color=COLORS["main"])
        e.set_image(url=member.display_avatar.url)
        await ctx.send(embed=e)

    @commands.command(name="serverinfo")
    async def serverinfo(self, ctx):
        g = ctx.guild
