    # ── /retype ──────────────────────────────────────────────────────────────
    @commands.hybrid_command(name="retype", description="Retype messages as their sender via webhook (APP badge)")
    async def retype(self, ctx: commands.Context, toggle: str, trigger: str = None, *, replacement: str = None):
        """
        /retype on                   — every message in server gets retyped as sender (APP badge, same content)
        /retype on <word> <newword>  — replace <word> with <newword> inside every message that contains it
        /retype off                  — disable global retype + clear all word subs
        /retype off <word>           — remove just that word substitution
        /retype list                 — show current status
        """
        # Premium or server owner only
        is_server_owner = ctx.guild and ctx.guild.owner_id == ctx.author.id
        if ctx.author.id != OWNER_ID and ctx.author.id not in PREMIUM_USERS and not is_server_owner:
            return await ctx.send(
                embed=discord.Embed(
                    description="🔒 `/retype` is **Premium only**. Server owners and Premium users can use this.",
                    color=COLORS["error"],
                ),
                ephemeral=False,
            )

        toggle = toggle.lower()
        gid = ctx.guild.id

        if toggle == "on":
            if not trigger:
                # Global mode — retype EVERY message as sender
                _RETYPE_ALL.add(gid)
                await ctx.send(
                    embed=discord.Embed(
                        title="🔄 Retype ON (Global)",
                        description="**Every message** in this server will be deleted and re-sent via webhook as the original sender.\n\nThe content is unchanged — but it shows with **APP badge** (your pfp + username but as an app).\n\n`/retype off` to disable.",
                        color=COLORS["success"],
                    ),
                    ephemeral=False,
                )
            else:
                # Word substitution mode
                if not replacement:
                    return await ctx.send(
                        embed=discord.Embed(description="**Usage:** `/retype on <trigger_word> <replacement_word>`\n\nExample: `/retype on raiding r4iding`", color=COLORS["warn"]),
                        ephemeral=False,
                    )
                if gid not in _RETYPE_GUILDS:
                    _RETYPE_GUILDS[gid] = {}
                _RETYPE_GUILDS[gid][trigger.lower()] = replacement
                await ctx.send(
                    embed=discord.Embed(
                        title="🔄 Word Substitution Added",
                        description=f"When anyone's message contains `{trigger.lower()}` it becomes `{replacement}`\n\n**Example:** `i like {trigger}` → `i like {replacement}`\n\nSent via webhook as the original sender (APP badge).",
                        color=COLORS["success"],
                    ),
                    ephemeral=False,
                )

        elif toggle == "off":
            if trigger:
                _RETYPE_GUILDS.get(gid, {}).pop(trigger.lower(), None)
                if not _RETYPE_GUILDS.get(gid):
                    _RETYPE_GUILDS.pop(gid, None)
                await ctx.send(
                    embed=discord.Embed(description=f"🔄 Removed substitution `{trigger.lower()}`", color=COLORS["error"]),
                    ephemeral=False,
                )
            else:
                _RETYPE_ALL.discard(gid)
                _RETYPE_GUILDS.pop(gid, None)
                await ctx.send(
                    embed=discord.Embed(description="🔄 Retype fully **OFF** — global mode disabled, all substitutions cleared.", color=COLORS["error"]),
                    ephemeral=False,
                )

        elif toggle == "list":
            global_on = gid in _RETYPE_ALL
            subs = _RETYPE_GUILDS.get(gid, {})
            desc = f"**Global retype:** {'✅ ON' if global_on else '❌ OFF'}\n\n"
            desc += "**Word substitutions:**\n"
            desc += "\n".join(f"`{t}` → `{r}`" for t, r in subs.items()) if subs else "None"
            await ctx.send(
                embed=discord.Embed(title="🔄 Retype Status", description=desc, color=COLORS["info"]),
                ephemeral=False,
            )

        else:
            await ctx.send(
                embed=discord.Embed(
                    title="🔄 /retype — Usage",
                    description=(
                        "`/retype on` — retype EVERY message as sender (APP badge)\n"
                        "`/retype on <word> <newword>` — replace word inside messages\n"
                        "`/retype off` — disable everything\n"
                        "`/retype off <word>` — remove one substitution\n"
                        "`/retype list` — see current status\n\n"
                        "**Example:** `/retype on raiding r4iding`\n"
                        "Someone types `yo i like raiding` → becomes `yo i like r4iding` (sent as them, APP badge)"
                    ),
                    color=COLORS["warn"],
                ),
                ephemeral=False,
            )

