    # ── /fakemsg ─────────────────────────────────────────────────────────────
    @commands.hybrid_command(name="fakemsg", description="Send a message as any user (webhook clones their pfp + username)")
    async def fakemsg(self, ctx: commands.Context, user_id: str, *, message: str):
        """
        /fakemsg <user_id> <message>
        Fetches the user by ID, clones their pfp + username, sends the message via
        webhook → appears with APP badge but looks exactly like that user.
        Premium / bot-owner only.
        """
        is_server_owner = ctx.guild and ctx.guild.owner_id == ctx.author.id
        if ctx.author.id != OWNER_ID and ctx.author.id not in PREMIUM_USERS and not is_server_owner:
            return await ctx.send(
                embed=discord.Embed(description="🔒 `/fakemsg` is **Premium only**.", color=COLORS["error"]),
                ephemeral=False,
            )

        # delete the slash-command invocation so nothing shows
        try:
            await ctx.message.delete()
        except Exception:
            pass

        # resolve target user
        try:
            uid_int = int(user_id.strip("<@!>"))
        except ValueError:
            return await ctx.send(
                embed=discord.Embed(description="❌ Invalid user ID. Use a numeric Discord user ID.", color=COLORS["error"]),
                ephemeral=False,
            )

        try:
            target = await bot.fetch_user(uid_int)
        except discord.NotFound:
            return await ctx.send(
                embed=discord.Embed(description=f"❌ User `{uid_int}` not found.", color=COLORS["error"]),
                ephemeral=False,
            )
        except Exception as ex:
            return await ctx.send(
                embed=discord.Embed(description=f"❌ Could not fetch user: {ex}", color=COLORS["error"]),
                ephemeral=False,
            )

        # build / reuse webhook
        ch = ctx.channel
        wh = None
        cached = _RETYPE_WEBHOOKS.get(ch.id)
        if cached:
            try:
                wh = discord.Webhook.from_url(cached, client=bot)
            except Exception:
                wh = None
                _RETYPE_WEBHOOKS.pop(ch.id, None)
        if wh is None:
            for existing in await ch.webhooks():
                if existing.name == "Coolbot":
                    _RETYPE_WEBHOOKS[ch.id] = existing.url
                    wh = existing
                    break
        if wh is None:
            wh = await ch.create_webhook(name="Coolbot")
            _RETYPE_WEBHOOKS[ch.id] = wh.url

        # send as the target user — their pfp + display name, APP badge
        target_name   = target.display_name
        target_avatar = str(target.display_avatar.url)
        try:
            await wh.send(message, username=target_name, avatar_url=target_avatar)
        except Exception as ex:
            await ctx.send(
                embed=discord.Embed(description=f"❌ Failed to send: {ex}", color=COLORS["error"]),
                ephemeral=False,
            )

