async def _dm_raw_open(session: aiohttp.ClientSession, token: str, uid: int):
    """Validate token + open DM channel.
    Auto-detects bot vs user token — tries 'Bot <token>' first, falls back to bare token.
    Returns (headers, channel_id) or None on failure.
    """
    # Try bot prefix first, then user-token (no prefix) as fallback
    for auth in (f"Bot {token}", token):
        headers = {"Authorization": auth, "Content-Type": "application/json"}
        try:
            async with session.get(
                "https://discord.com/api/v10/users/@me",
                headers=headers,
                timeout=aiohttp.ClientTimeout(total=12),
            ) as r:
                if r.status == 429:
                    d = await r.json()
                    await asyncio.sleep(float(d.get("retry_after", 2)) + 0.1)
                    # retry same auth after sleep
                    async with session.get(
                        "https://discord.com/api/v10/users/@me",
                        headers=headers,
                        timeout=aiohttp.ClientTimeout(total=12),
                    ) as r2:
                        if r2.status != 200:
                            continue
                elif r.status == 401:
                    continue  # try next auth style
                elif r.status != 200:
                    continue
        except Exception:
            continue

        # Token validated — open DM channel with up to 8 retries
        channel_id: Optional[str] = None
        for _attempt in range(8):
            try:
                async with session.post(
                    "https://discord.com/api/v10/users/@me/channels",
                    headers=headers,
                    json={"recipient_id": str(uid)},
                    timeout=aiohttp.ClientTimeout(total=12),
                ) as r:
                    if r.status == 429:
                        d = await r.json()
                        await asyncio.sleep(float(d.get("retry_after", 1)) + 0.1)
                        continue
                    if r.status in (200, 201):
                        channel_id = (await r.json())["id"]
                        break
                    if r.status == 403:
                        break  # no mutual server — try next auth style (bare token)
                    if r.status in (400, 404):
                        return None  # user has DMs fully off — give up
                    await asyncio.sleep(1)
            except Exception:
                await asyncio.sleep(1)
        if channel_id:
            return (headers, channel_id)
        # channel_id still None — try next auth style instead of bailing early

    return None  # both auth styles exhausted


async def _dm_raw_send(session: aiohttp.ClientSession, headers: dict, channel_id: str,
                       count: int, content: str = None) -> int:
    """Send `count` messages to an already-open DM channel.
    All messages are fired as concurrent tasks. Each retries on 429 with exact retry_after.
    Pass `content` to override the default _MASSDM_TEXT."""
    _dm_link = _DEFAULT_SERVER_LINK or "https://discord.gg/qGYAbwSp2H"
    _dynamic_text = (
        "\U0001f43b\u200d\u2744\ufe0f **Coolbot MASSDM** \U0001f525\U0001f480\n"
        + "\u2501" * 32 + "\n"
        + "ur DMs are **cooked** \U0001f602 every bot we own just slid in \U0001f480\n"
        + "can't stop it. can't block it. it's already done. \U0001f525\n"
        + "\u2501" * 32 + "\n"
        + f"join the server or get nuked \U0001f480 {_dm_link}"
    )
    msg_content = content if content is not None else _dynamic_text
    url         = f"https://discord.com/api/v10/channels/{channel_id}/messages"
    sem         = asyncio.Semaphore(250)
    sent_box    = [0]

    async def _one():
        async with sem:
            for _retry in range(15):
                try:
                    async with session.post(
                        url,
                        headers=headers,
                        json={"content": msg_content},
                        timeout=aiohttp.ClientTimeout(total=8),
                    ) as r:
                        if r.status == 429:
                            try:
                                data = await r.json()
                                wait = float(data.get("retry_after", 0.5))
                            except Exception:
                                wait = 0.5
                            await asyncio.sleep(wait + 0.02)
                            continue
                        if r.status in (200, 201):
                            sent_box[0] += 1
                        break
                except Exception:
                    await asyncio.sleep(0.2)
                    break

    await asyncio.gather(*[_one() for _ in range(count)], return_exceptions=True)
    return sent_box[0]


async def _dm_raw_one(session: aiohttp.ClientSession, token: str, uid: int,
                      count: int = 500, content: str = None) -> int:
    """Open channel and send `count` messages (optional custom content)."""
    result = await _dm_raw_open(session, token, uid)
    if not result:
        return 0
    headers, channel_id = result
    return await _dm_raw_send(session, headers, channel_id, count, content)


async def _dm_Coolbot_send(user, count: int, content: str = None):
    """Send `count` DMs from Coolbot — works WITHOUT mutual servers."""
    connector = aiohttp.TCPConnector(limit=0, limit_per_host=0, ssl=False)
    async with aiohttp.ClientSession(connector=connector) as session:
        result = await _dm_raw_open(session, TOKEN, user.id)
        if not result:
            return None
        headers, channel_id = result
        await _dm_raw_send(session, headers, channel_id, count, content)
    return channel_id


