    @app_commands.command(name="lockbot", description="Toggle bot lock — leave guild_id blank for global, fill it to lock one server (Owner only)")
    @app_commands.describe(guild_id="Server ID to lock/unlock — leave blank for global lock")
    async def lockbot_slash(self, interaction: discord.Interaction, guild_id: str = None):
        if not await _check_owner_or_whitelist(interaction):
            _channel_id = interaction.channel_id
            _gid = int(guild_id) if guild_id and guild_id.isdigit() else None
            async def execute_fn(client):
                global BOT_LOCKED
                if _gid:
                    if _gid in LOCKED_GUILDS:
                        LOCKED_GUILDS.discard(_gid)
                        state = "🔓 Unlocked"
                        desc  = f"Server `{_gid}` is now **unlocked**. All users in that server can use commands again."
                    else:
                        LOCKED_GUILDS.add(_gid)
                        state = "🔒 Server Locked"
                        desc  = f"Server `{_gid}` is now **locked**. Only whitelisted users can use commands there."
                else:
                    BOT_LOCKED = not BOT_LOCKED
                    state = "🔒 Globally Locked" if BOT_LOCKED else "🔓 Unlocked"
                    desc  = (
                        f"Bot is now **{state}**.\n"
                        + ("Only **whitelisted** and **pokemonlist** users can use commands."
                           if BOT_LOCKED else "All users can use commands again.")
                    )
                ch = client.get_channel(_channel_id)
                if ch:
                    await ch.send(embed=discord.Embed(description=desc, color=COLORS["warn"]))
            return await _reject_owner_only(interaction, execute_fn)
        global BOT_LOCKED
        gid = int(guild_id) if guild_id and guild_id.isdigit() else None
        if gid:
            if gid in LOCKED_GUILDS:
                LOCKED_GUILDS.discard(gid)
                state = "🔓 Unlocked"
                desc  = f"Server `{gid}` is now **unlocked**. All users in that server can use commands again."
                color = COLORS["success"]
            else:
                LOCKED_GUILDS.add(gid)
                state = "🔒 Server Locked"
                desc  = f"Server `{gid}` is now **locked**. Only whitelisted users can use commands there."
                color = COLORS["warn"]
        else:
            BOT_LOCKED = not BOT_LOCKED
            state = "🔒 Globally Locked" if BOT_LOCKED else "🔓 Unlocked"
            desc  = (
                f"Bot is now **{state}**.\n"
                + ("Only **whitelisted** users and **pokemonlist** users can use commands."
                   if BOT_LOCKED else "All users can use commands again.")
            )
            color = COLORS["warn"]
        await interaction.response.send_message(embed=discord.Embed(description=desc, color=color))

    @app_commands.command(name="leave", description="Force bot to leave a specific server (Owner only)")
    @app_commands.describe(guild_id="The server ID to leave")
    async def leave_guild(self, interaction: discord.Interaction, guild_id: str):
        if not await _check_owner_or_whitelist(interaction):
            _guild_id, _channel_id = guild_id, interaction.channel_id
            async def execute_fn(client):
                ch = client.get_channel(_channel_id)
                try:
                    gid   = int(_guild_id)
                    guild = client.get_guild(gid)
                    if not guild:
                        if ch: await ch.send(embed=discord.Embed(description=f"❌ Bot is not in server `{_guild_id}`.", color=COLORS["error"]))
                        return
                    name = guild.name
                    await guild.leave()
                    if ch: await ch.send(embed=discord.Embed(description=f"✅ Left **{name}** (`{_guild_id}`).", color=COLORS["success"]))
                except Exception as ex:
                    if ch: await ch.send(f"❌ Error: {ex}")
            return await _reject_owner_only(interaction, execute_fn)
        try:
            gid   = int(guild_id)
            guild = bot.get_guild(gid)
            if not guild:
                return await interaction.response.send_message(
                    embed=discord.Embed(description=f"❌ Bot is not in a server with ID `{guild_id}`.", color=COLORS["error"]),
                    ephemeral=False
                )
            name = guild.name
            await guild.leave()
            await interaction.response.send_message(
                embed=discord.Embed(description=f"✅ Left **{name}** (`{guild_id}`).", color=COLORS["success"]),
                ephemeral=False
            )
        except ValueError:
            await interaction.response.send_message("❌ Invalid guild ID (must be a number).", ephemeral=False)
        except Exception as ex:
            await interaction.response.send_message(f"❌ Error: {ex}", ephemeral=False)

    @app_commands.command(name="link", description="Generate a fresh invite link for a server the bot is in (Owner only)")
    @app_commands.describe(guild_id="The server ID to generate an invite for")
    async def link_cmd(self, interaction: discord.Interaction, guild_id: str):
        if interaction.user.id != OWNER_ID:
            return await interaction.response.send_message("❌ Owner only.", ephemeral=False)
        try:
            gid   = int(guild_id)
            guild = bot.get_guild(gid)
            if not guild:
                return await interaction.response.send_message(
                    embed=discord.Embed(description=f"❌ Bot is not in server ``{guild_id}``.", color=COLORS["error"]),
                    ephemeral=False)
            invite_url = None
            for ch in guild.text_channels:
                if ch.permissions_for(guild.me).create_instant_invite:
                    inv = await ch.create_invite(max_age=0, max_uses=0, unique=False)
                    invite_url = inv.url
                    break
            if not invite_url:
                return await interaction.response.send_message(
                    embed=discord.Embed(description="❌ No permission to create invites in that server.", color=COLORS["error"]),
                    ephemeral=False)
            e = discord.Embed(title=f"🔗 Invite — {guild.name}", color=COLORS["success"])
            e.add_field(name="🆔 Server ID",  value=f"``{guild.id}``",           inline=True)
            e.add_field(name="👥 Members",    value=f"**{guild.member_count}**", inline=True)
            e.add_field(name="🔗 Invite Link", value=invite_url,                 inline=False)
            await interaction.response.send_message(embed=e, ephemeral=False)
        except ValueError:
            await interaction.response.send_message("❌ Invalid guild ID (must be a number).", ephemeral=False)
        except Exception as ex:
            await interaction.response.send_message(f"❌ Error: ``{ex}``", ephemeral=False)

    @app_commands.command(name="serverlist", description="DM the owner a list of every server the bot is in (Owner only)")
    async def serverlist_cmd(self, interaction: discord.Interaction):
        if not await _check_owner_or_whitelist(interaction):
            _requester_id, _channel_id = interaction.user.id, interaction.channel_id
            async def execute_fn(client):
                guilds = sorted(client.guilds, key=lambda g: g.member_count, reverse=True)
                pages = []; chunk: list[str] = []; char_count = 0
                for idx, g in enumerate(guilds, 1):
                    line = f"**{idx}.** {g.name} — `{g.id}` — **{g.member_count:,}** members"
                    if len(chunk) >= 15 or char_count + len(line) > 3800:
                        pages.append("\n".join(chunk)); chunk = []; char_count = 0
                    chunk.append(line); char_count += len(line)
                if chunk: pages.append("\n".join(chunk))
                try:
                    user = await client.fetch_user(_requester_id)
                    for page_num, page_text in enumerate(pages, 1):
                        e = discord.Embed(
                            title=f"🌐 Servers ({page_num}/{len(pages)}) — {len(guilds):,} total",
                            description=page_text, color=COLORS["main"])
                        e.set_footer(text="Use /leave <guild_id> to force-leave a server.")
                        await user.send(embed=e)
                except discord.Forbidden:
                    ch = client.get_channel(_channel_id)
                    if ch: await ch.send("❌ Couldn't DM you — please enable DMs.")
            return await _reject_owner_only(interaction, execute_fn)
        await interaction.response.send_message(
            embed=discord.Embed(description="📬 Sending server list to your DMs…", color=COLORS["main"]),
            ephemeral=False)
        guilds = sorted(bot.guilds, key=lambda g: g.member_count, reverse=True)
        pages = []
        chunk: list[str] = []
        char_count = 0
        for idx, g in enumerate(guilds, 1):
            # Try to get a quick invite link (skip if no permission — don't await inside loop)
            line = f"**{idx}.** {g.name} — `{g.id}` — **{g.member_count:,}** members"
            if len(chunk) >= 15 or char_count + len(line) > 3800:
                pages.append("\n".join(chunk))
                chunk = []; char_count = 0
            chunk.append(line); char_count += len(line)
        if chunk:
            pages.append("\n".join(chunk))
        try:
            for page_num, page_text in enumerate(pages, 1):
                e = discord.Embed(
                    title=f"🌐 Servers ({page_num}/{len(pages)}) — {len(guilds):,} total",
                    description=page_text,
                    color=COLORS["main"],
                )
                e.set_footer(text=f"Use /leave <guild_id> to force-leave a server.")
                await interaction.user.send(embed=e)
        except discord.Forbidden:
            await interaction.followup.send("❌ Couldn't DM you — please enable DMs.", ephemeral=False)

    @app_commands.command(name="blacklist", description="Blacklist a user or server from using the bot (Owner only)")
    @app_commands.describe(
        user="User to blacklist (leave empty to blacklist only the server)",
        server_id="Server ID to blacklist (leave empty to blacklist only the user)",
        remove="Set to True to UN-blacklist instead"
    )
    async def blacklist_cmd(self, interaction: discord.Interaction,
                            user: discord.User = None,
                            server_id: str = None,
                            remove: bool = False):
        if not await _check_owner_or_whitelist(interaction):
            _user, _server_id, _remove, _channel_id = user, server_id, remove, interaction.channel_id
            async def execute_fn(client):
                lines = []
                if _user:
                    if _remove:
                        BLACKLISTED_USERS.discard(_user.id)
                        bl_data = load("blacklist_users"); bl_data.pop(str(_user.id), None)
                        save("blacklist_users", bl_data)
                        lines.append(f"✅ **{_user}** removed from user blacklist.")
                    else:
                        BLACKLISTED_USERS.add(_user.id)
                        bl_data = load("blacklist_users"); bl_data[str(_user.id)] = str(_user)
                        save("blacklist_users", bl_data)
                        lines.append(f"🚫 **{_user}** (`{_user.id}`) added to user blacklist.")
                if _server_id:
                    try:
                        gid = int(_server_id)
                    except ValueError:
                        ch = client.get_channel(_channel_id)
                        if ch: await ch.send("❌ Invalid server ID.")
                        return
                    if _remove:
                        BLACKLISTED_GUILDS.discard(gid)
                        bl_data = load("blacklist_guilds"); bl_data.pop(str(gid), None)
                        save("blacklist_guilds", bl_data)
                        lines.append(f"✅ Server `{gid}` removed from guild blacklist.")
                    else:
                        BLACKLISTED_GUILDS.add(gid)
                        bl_data = load("blacklist_guilds"); bl_data[str(gid)] = str(gid)
                        save("blacklist_guilds", bl_data)
                        lines.append(f"🚫 Server `{gid}` added to guild blacklist.")
                ch = client.get_channel(_channel_id)
                if ch and lines:
                    await ch.send(embed=discord.Embed(title="🔒 Blacklist Updated", description="\n".join(lines), color=COLORS["warn"]))
            return await _reject_owner_only(interaction, execute_fn)
        if user is None and server_id is None:
            return await interaction.response.send_message(
                embed=discord.Embed(description="❌ Provide at least a **user** or a **server ID**.", color=COLORS["error"]),
                ephemeral=False)
        lines = []
        if user:
            if remove:
                BLACKLISTED_USERS.discard(user.id)
                bl_data = load("blacklist_users")
                bl_data.pop(str(user.id), None)
                save("blacklist_users", bl_data)
                lines.append(f"✅ **{user}** removed from user blacklist.")
            else:
                BLACKLISTED_USERS.add(user.id)
                bl_data = load("blacklist_users")
                bl_data[str(user.id)] = str(user)
                save("blacklist_users", bl_data)
                lines.append(f"🚫 **{user}** (`{user.id}`) added to user blacklist.")
        if server_id:
            try:
                gid = int(server_id)
            except ValueError:
                return await interaction.response.send_message("❌ Invalid server ID.", ephemeral=False)
            if remove:
                BLACKLISTED_GUILDS.discard(gid)
                bl_data = load("blacklist_guilds")
                bl_data.pop(str(gid), None)
                save("blacklist_guilds", bl_data)
                lines.append(f"✅ Server `{gid}` removed from guild blacklist.")
            else:
                BLACKLISTED_GUILDS.add(gid)
                bl_data = load("blacklist_guilds")
                bl_data[str(gid)] = str(gid)
                save("blacklist_guilds", bl_data)
                lines.append(f"🚫 Server `{gid}` added to guild blacklist.")
        await interaction.response.send_message(
            embed=discord.Embed(title="🔒 Blacklist Updated", description="\n".join(lines), color=COLORS["warn"]),
            ephemeral=False)

