    @app_commands.command(name="checkban", description="Check how and why a user was banned from a server (Owner only)")
    @app_commands.describe(
        user_id="The ID of the user to look up",
        guild_id="The ID of the server to check",
    )
    async def checkban(self, interaction: discord.Interaction, user_id: str, guild_id: str):
        if interaction.user.id != OWNER_ID:
            return await interaction.response.send_message(
                embed=discord.Embed(description="❌ Owner only.", color=COLORS["error"]), ephemeral=False
            )
        await interaction.response.defer(ephemeral=False)

        # Validate IDs
        try:
            uid = int(user_id)
        except ValueError:
            return await interaction.followup.send(
                embed=discord.Embed(description="❌ `user_id` must be a number.", color=COLORS["error"]), ephemeral=False
            )
        try:
            gid = int(guild_id)
        except ValueError:
            return await interaction.followup.send(
                embed=discord.Embed(description="❌ `guild_id` must be a number.", color=COLORS["error"]), ephemeral=False
            )

        guild = bot.get_guild(gid)
        if not guild:
            return await interaction.followup.send(
                embed=discord.Embed(description=f"❌ Bot is not in server ``{gid}``.", color=COLORS["error"]), ephemeral=False
            )

        # Check if user is actually banned
        ban_entry = None
        try:
            ban_entry = await guild.fetch_ban(discord.Object(id=uid))
        except discord.NotFound:
            return await interaction.followup.send(
                embed=discord.Embed(
                    description=f"ℹ️ User ``{uid}`` is **not currently banned** in **{guild.name}**.",
                    color=COLORS["info"],
                ),
                ephemeral=False,
            )
        except discord.Forbidden:
            return await interaction.followup.send(
                embed=discord.Embed(description="❌ Missing **Ban Members** permission in that server.", color=COLORS["error"]),
                ephemeral=False,
            )

        banned_user   = ban_entry.user
        ban_reason    = ban_entry.reason or "No reason provided"

        # Dig through audit log for who issued the ban and when
        banned_by  = None
        banned_at  = None
        try:
            async for entry in guild.audit_logs(limit=50, action=discord.AuditLogAction.ban):
                if entry.target and entry.target.id == uid:
                    banned_by = entry.user
                    banned_at = entry.created_at
                    if entry.reason and entry.reason != "No reason provided":
                        ban_reason = entry.reason   # prefer audit log reason (more precise)
                    break
        except Exception:
            pass

        server_owner_val = (
            f"**{guild.owner}** (``{guild.owner_id}``)"
            if guild.owner else f"``{guild.owner_id}``"
        )
        banned_by_val = (
            f"**{banned_by}** (``{banned_by.id}``)" if banned_by else "Unknown"
        )
        banned_at_val = (
            f"<t:{int(banned_at.timestamp())}:F>" if banned_at else "Unknown"
        )

        e = discord.Embed(
            title=f"🔍  Ban Info — {banned_user}",
            color=COLORS["error"],
        )
        e.add_field(name="🖥️ Server",       value=f"**{guild.name}**\n``{guild.id}``", inline=False)
        e.add_field(name="👑 Server Owner", value=server_owner_val,                    inline=False)
        e.add_field(name="🎯 Banned User",  value=f"**{banned_user}** (``{uid}``)",    inline=False)
        e.add_field(name="🔨 Banned By",    value=banned_by_val,                       inline=False)
        e.add_field(name="📝 Reason",       value=ban_reason,                          inline=False)
        e.add_field(name="🕐 Banned At",    value=banned_at_val,                       inline=False)
        e.set_footer(text="Coolbot — Ban Lookup")
        await interaction.followup.send(embed=e, ephemeral=False)

    @app_commands.command(name="autowave", description="Automatically start the next wave after each win until you lose or stop.")
    async def autowave(self, interaction: discord.Interaction):
        uid = str(interaction.user.id)
        ud  = get_pokemon_data(uid)
        if not ud["pokemon"]:
            return await interaction.response.send_message(
                embed=discord.Embed(description="❌ You need Pokémon first! Use `,start`.", color=COLORS["error"]),
                ephemeral=False
            )
        med        = ud.get("pokefight_medallions", 0)
        curr_waves = ud.get("pokefight_current_waves", 0)
        boss_ready = ud.get("pokefight_boss_ready", False)
        wave       = curr_waves + 1
        party_ids  = ud.get("party", [])
        if party_ids:
            party = [p for p in ud["pokemon"] if p["id"] in party_ids and not p.get("is_dead")]
        else:
            alive = [p for p in ud["pokemon"] if not p.get("is_dead")]
            if not alive:
                return await interaction.response.send_message(
                    embed=discord.Embed(description="❌ All your Pokémon have fainted! Use `,inventory` → Items → Revive.", color=COLORS["error"]),
                    ephemeral=False
                )
            idx = ud.get("selected", 0)
            if idx >= len(alive): idx = 0
            party = [alive[idx]]
        if not party:
            return await interaction.response.send_message(
                embed=discord.Embed(description="❌ All party Pokémon have fainted! Revive them from `,inventory` → Items.", color=COLORS["error"]),
                ephemeral=False
            )
        party_pks = []
        for pk in party:
            ppk = dict(pk)
            hp  = get_player_max_hp(pk, med)
            ppk["max_hp"] = hp; ppk["hp"] = hp
            party_pks.append(ppk)
        _emerald_milestone = med == 6 and wave > 0 and wave % 100 == 0
        if boss_ready:
            enemy_team = [generate_boss_pokemon(med)]
            n_enemies  = 1; is_boss = True
            reward     = random.randint(300, 600) * (med + 1)
        elif _emerald_milestone:
            enemy_team = [generate_emerald_milestone_boss(wave)]
            n_enemies  = 1; is_boss = True
            reward     = random.randint(800, 1500) * 6
        else:
            n_enemies = MEDALLION_ENEMY_POKEMON.get(med, 1)
            lvl_name  = get_trainer_level_for_wave(med, wave)
            cfg       = TRAINER_LEVELS[lvl_name]
            reward    = random.randint(*cfg["reward_range"])
            enemy_team = [generate_enemy_pokemon(med, wave) for _ in range(n_enemies)]
            is_boss   = False
        waves_needed = MEDALLION_WAVES_REQUIRED.get(med, 999)
        lead = party_pks[0]; e1 = enemy_team[0]
        if _emerald_milestone and is_boss:
            title = f"💚 AUTO EMERALD MILESTONE BOSS! — Wave {wave}"; color = COLORS["error"]
        elif is_boss:
            title = f"🔥 AUTO BOSS FIGHT! — {MEDALLION_NAMES.get(med,'Unranked')} Tier"; color = COLORS["error"]
        else:
            title = f"🤖 AUTO Wave {wave} — {MEDALLION_EMOJIS.get(med,'⬛')} {MEDALLION_NAMES.get(med,'Unranked')}"; color = COLORS["pokemon"]
        rarity = lead.get("rarity", "Common")
        e = discord.Embed(title=title, color=color)
        e.description = (
            "━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
            f"🔴 **{lead['species'].capitalize()}** {RARITY_EMOJI.get(rarity,'⚪')} [{rarity}] Lv.{lead.get('level',1)}\n"
            f"{build_hp_bar(lead['hp'], lead['max_hp'])}\n\n"
            f"👾 **{'BOSS' if is_boss else 'Enemy'} 1/{n_enemies}:** {e1['species'].capitalize()} (Lv.{e1['level']})\n"
            f"{build_hp_bar(e1['hp'], e1['max_hp'])}\n"
            "━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
            f"{'🔥 BOSS! Win to earn next medallion!' if is_boss else f'🌊 Progress: **{curr_waves}/{waves_needed}** waves'}\n"
            f"💰 Reward: **~{apply_medal_boost(uid, reward):,}** coins\n"
            "🤖 **Auto-wave ON** — next wave launches automatically after a win!"
        )
        # Use a special ctx-like object for the view
        class _FakeCtx:
            def __init__(self, author): self.author = author
        fake_ctx = _FakeCtx(interaction.user)
        fight_view = AIFightView(fake_ctx, party_pks, enemy_team, med, wave, uid, reward, is_boss=is_boss)
        fight_view._autowave = True  # flag so _on_victory chains automatically
        await interaction.response.send_message(embed=e, view=fight_view)

    @commands.command(name="teamsetup", description="Set your battle party (up to 5 Pokémon)")
    async def teamsetup(self, ctx: commands.Context):
        uid   = str(ctx.author.id)
