    @commands.command(name="preroll")
    async def preroll(self, ctx, pokemon_id: int):
        """Reroll a Pokémon's trait for coins."""
        uid = str(ctx.author.id); ud = get_pokemon_data(uid)
        pk  = next((p for p in ud["pokemon"] if p["id"] == pokemon_id), None)
        if not pk:
            return await ctx.send(embed=discord.Embed(description=f"❌ No Pokémon with ID `{pokemon_id}`.", color=COLORS["error"]))
        rarity = pk.get("rarity","Common")
        cost   = TRAIT_REROLL_COST.get(rarity, 2500)
        if ud.get("balance",0) < cost:
            return await ctx.send(embed=discord.Embed(description=f"❌ Need **{cost:,}** coins to reroll — have **{ud.get('balance',0):,}**.", color=COLORS["error"]))
        pk["trait"] = roll_trait_for_pokemon(pk)
        ud["balance"] -= cost
        save_pokemon_data(uid, ud)
        tinfo = POKEMON_TRAITS.get(pk["trait"],{})
        if pk["trait"] in SECRET_SUPREME_TRAITS:
            trait_cat = next((f"{v['emoji']} **{k}**" for k,v in TRAIT_CATEGORIES.items() if pk["trait"] in v["traits"]), "—")
            e = discord.Embed(
                title=f"🚨 {pk['species'].capitalize()} — Rare Trait Landed!",
                description=f"You hit a {trait_cat} trait!",
                color=0xFF0000 if pk["trait"] in TRAIT_CATEGORIES["Secret"]["traits"] else 0x00FFFF
            )
            e.add_field(name="Trait", value=f"{tinfo.get('emoji','✦')} **{pk['trait']}**" if tinfo else pk["trait"], inline=True)
            if tinfo: e.add_field(name="Effect", value=tinfo.get("desc",""), inline=False)
            e.set_footer(text=f"Cost: {cost:,} coins | Balance: {ud['balance']:,}")
        else:
            e = discord.Embed(
                title=f"🎲 {pk['species'].capitalize()} — Trait Rerolled",
                description=f"New trait: {tinfo.get('emoji','✦')} **{pk['trait']}**" if tinfo else f"New trait: **{pk['trait']}**",
                color=RARITY_COLOR.get(rarity, COLORS["pokemon"])
            )
            if tinfo: e.add_field(name="Effect", value=tinfo.get("desc",""), inline=False)
            e.set_footer(text=f"Cost: {cost:,} coins | Balance: {ud['balance']:,}")
        await ctx.send(embed=e)

