    @commands.command(name="release")
    async def release(self, ctx, pokemon_id: int):
        uid = str(ctx.author.id); ud = get_pokemon_data(uid)
        pk  = next((p for p in ud["pokemon"] if p["id"]==pokemon_id), None)
        if not pk:
            return await ctx.send(embed=discord.Embed(description=f"❌ No Pokémon with ID `{pokemon_id}`.", color=COLORS["error"]))
        if pk.get("favorite"):
            return await ctx.send(embed=discord.Embed(description="❌ Can't release a favourited Pokémon!", color=COLORS["error"]))
        shiny_txt = "✨ Shiny " if pk.get("shiny") else ""
        e = discord.Embed(title="⚠️ Release Pokémon?",
            description=f"Release **{shiny_txt}{pk['species'].capitalize()}** (Lv.{pk.get('level',1)})?\n\n**This cannot be undone!**",
            color=COLORS["warn"])
        e.set_thumbnail(url=pokemon_sprite_url(pk.get("pokedex_id",0), pk.get("shiny",False)))
        view = discord.ui.View(timeout=30)
        confirm_btn = discord.ui.Button(label="✅ Yes, release", style=discord.ButtonStyle.danger)
        cancel_btn  = discord.ui.Button(label="❌ Cancel",       style=discord.ButtonStyle.secondary)
        async def confirm_cb(interaction: discord.Interaction):
            if interaction.user.id != ctx.author.id: return await interaction.response.send_message("Not yours!", ephemeral=False)
            ud2 = get_pokemon_data(uid); pk2 = next((p for p in ud2["pokemon"] if p["id"]==pokemon_id), None)
            if not pk2:
                return await interaction.response.edit_message(embed=discord.Embed(description="❌ Already gone.", color=COLORS["error"]), view=None)
            ud2["pokemon"].remove(pk2)
            if ud2.get("selected",0) >= len(ud2["pokemon"]): ud2["selected"] = 0
            save_pokemon_data(uid, ud2)
            for c in view.children: c.disabled = True
            await interaction.response.edit_message(embed=discord.Embed(description=f"🌿 **{shiny_txt}{pk2['species'].capitalize()}** was released.", color=COLORS["warn"]), view=view)
        async def cancel_cb(interaction: discord.Interaction):
            if interaction.user.id != ctx.author.id: return await interaction.response.send_message("Not yours!", ephemeral=False)
            for c in view.children: c.disabled = True
            await interaction.response.edit_message(embed=discord.Embed(description="✅ Release cancelled.", color=COLORS["success"]), view=view)
        confirm_btn.callback = confirm_cb; cancel_btn.callback = cancel_cb
        view.add_item(confirm_btn); view.add_item(cancel_btn)
        await ctx.send(embed=e, view=view)

