    @commands.command(name="pokefight", aliases=["pf"])
    async def pokefight(self, ctx):
        uid = str(ctx.author.id); ud = get_pokemon_data(uid)
        if not ud["pokemon"]:
            return await ctx.send(embed=discord.Embed(description="❌ You need Pokémon first! Use `,start`.", color=COLORS["error"]))
        med        = ud.get("pokefight_medallions",0)
        curr_waves = ud.get("pokefight_current_waves",0)
        boss_ready = ud.get("pokefight_boss_ready",False)
        wave       = curr_waves + 1
        party_ids  = ud.get("party",[])
        if party_ids:
            party = [p for p in ud["pokemon"] if p["id"] in party_ids and not p.get("is_dead")]
        else:
            alive = [p for p in ud["pokemon"] if not p.get("is_dead")]
            if not alive:
                return await ctx.send(embed=discord.Embed(description="❌ All your Pokémon have fainted! Use `,inventory` → Items → Revive.", color=COLORS["error"]))
            idx = ud.get("selected",0)
            if idx >= len(alive): idx = 0
            party = [alive[idx]]
        if not party:
            return await ctx.send(embed=discord.Embed(description="❌ All party Pokémon have fainted! Revive them from `,inventory` → Items.", color=COLORS["error"]))
        party_pks = []
        for pk in party:
            ppk = dict(pk)
            hp  = get_player_max_hp(pk, med)
            ppk["max_hp"] = hp; ppk["hp"] = hp
            party_pks.append(ppk)
        _emerald_milestone = med == 6 and wave > 0 and wave % 100 == 0
        if boss_ready:
            enemy_team = [generate_boss_pokemon(med)]
            n_enemies  = 1; is_boss = True
            reward     = random.randint(300,600) * (med+1)
        elif _emerald_milestone:
            enemy_team = [generate_emerald_milestone_boss(wave)]
            n_enemies  = 1; is_boss = True
            reward     = random.randint(800, 1500) * 6
        else:
            n_enemies = MEDALLION_ENEMY_POKEMON.get(med,1)
            lvl_name  = get_trainer_level_for_wave(med, wave)
            cfg       = TRAINER_LEVELS[lvl_name]
            reward    = random.randint(*cfg["reward_range"])
            enemy_team= [generate_enemy_pokemon(med, wave) for _ in range(n_enemies)]
            is_boss   = False
        waves_needed = MEDALLION_WAVES_REQUIRED.get(med,999)
        lead = party_pks[0]; e1 = enemy_team[0]
        if _emerald_milestone and is_boss:
            title = f"💚 EMERALD MILESTONE BOSS! — Wave {wave}"; color = COLORS["error"]
        elif is_boss:
            title = f"🔥 BOSS FIGHT! — {MEDALLION_NAMES.get(med,'Unranked')} Tier"; color = COLORS["error"]
        else:
            title = f"{MEDALLION_EMOJIS.get(med,'⬛')} Wave {wave} — {MEDALLION_NAMES.get(med,'Unranked')}"; color = COLORS["pokemon"]
        rarity = lead.get("rarity","Common")
        e = discord.Embed(title=title, color=color)
        e.description = (
            f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
            f"🔴 **{lead['species'].capitalize()}** {RARITY_EMOJI.get(rarity,'⚪')} [{rarity}] Lv.{lead.get('level',1)}\n"
            f"{build_hp_bar(lead['hp'], lead['max_hp'])}\n\n"
            f"👾 **{'BOSS' if is_boss else 'Enemy'} 1/{n_enemies}:** {e1['species'].capitalize()} (Lv.{e1['level']})\n"
            f"{build_hp_bar(e1['hp'], e1['max_hp'])}\n"
            f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
            f"{'🔥 BOSS! Win to earn next medallion!' if is_boss else f'🌊 Progress: **{curr_waves}/{waves_needed}** waves'}\n"
            f"💰 Reward: **~{apply_medal_boost(uid, reward):,}** coins"
        )
        view = AIFightView(ctx, party_pks, enemy_team, med, wave, uid, reward, is_boss=is_boss)
        # ── ANIMATION ──
        _pf_frames = [
            ("⚔️ Scanning for opponents…", "░░░░░░░░░░"),
            ("⚔️ Opponent found!", "████░░░░░░"),
            ("⚔️ Loading battle…", "████████░░"),
            ("⚔️ Battle starting!", "██████████"),
        ]
        _pf1 = discord.Embed(title=title, description=f"`{_pf_frames[0][1]}` {_pf_frames[0][0]}", color=color)
        _pfmsg = await ctx.send(embed=_pf1)
        for _pft, _pfb in _pf_frames[1:]:
            await asyncio.sleep(0.45)
            _pfx = discord.Embed(title=title, description=f"`{_pfb}` {_pft}", color=color)
            await _pfmsg.edit(embed=_pfx)
        await asyncio.sleep(0.45)
        await _pfmsg.edit(embed=e, view=view)


