    @commands.command(name="pdaily")
    @commands.cooldown(1, 3, commands.BucketType.user)
    async def pdaily(self, ctx):
        uid = str(ctx.author.id); ud = get_pokemon_data(uid)
        now = datetime.now(timezone.utc); last_str = ud.get("last_daily")
        if last_str:
            last = datetime.fromisoformat(last_str); diff = (now-last).total_seconds()
            if diff < 86400:
                remaining = 86400-diff; h,r = divmod(int(remaining),3600); m2=r//60
                return await ctx.send(embed=discord.Embed(description=f"⏰ Come back in **{h}h {m2}m**!", color=COLORS["warn"]))
            ud["daily_streak"] = ud.get("daily_streak",0)+1 if diff < 172800 else 1
        else:
            ud["daily_streak"] = 1
        streak = ud.get("daily_streak",1); bonus = min(streak-1,6)*50
        total  = apply_medal_boost(uid, DAILY_COINS+bonus)
        ud["balance"] = ud.get("balance",0)+total; ud["last_daily"] = now.isoformat()
        save_pokemon_data(uid, ud)
        increment_quest_stat(uid, "quest_daily_today")
        e = discord.Embed(title="🎁 Daily Reward!", color=COLORS["success"])
        e.add_field(name="💰 Coins",  value=f"**+{total:,}**",      inline=True)
        e.add_field(name="🔥 Streak", value=f"**{streak}** day(s)", inline=True)
        e.add_field(name="💳 Balance",value=f"**{ud['balance']:,}**",inline=True)
        if bonus > 0: e.add_field(name="⭐ Streak Bonus", value=f"+{bonus} coins!", inline=False)
        mult = get_coin_multiplier(uid)
        if mult > 1.0: e.add_field(name="🎖️ Boost", value=f"**{mult:.1f}x** active!", inline=False)
        # ── ANIMATION ──
        _bars = ["░░░░░░░░░░","██░░░░░░░░","████░░░░░░","██████░░░░","████████░░","██████████"]
        _labels = ["Unwrapping…","Tearing ribbon…","Opening box…","Almost there…","Done!",""]
        _da1 = discord.Embed(title="🎁 Daily Reward!", description=f"`{_bars[0]}` {_labels[0]}", color=0x00B0F4)
        _dmsg2 = await ctx.send(embed=_da1)
        for _bi in range(1, 5):
            await asyncio.sleep(0.4)
            _dax = discord.Embed(title="🎁 Daily Reward!", description=f"`{_bars[_bi]}` {_labels[_bi]}", color=0x00B0F4)
            await _dmsg2.edit(embed=_dax)
        await asyncio.sleep(0.4)
        await _dmsg2.edit(embed=e)

